CREATE OR REPLACE FUNCTION public.aka_agent_claim_campaign_runtime_checked(p_campaign_id bigint, p_account_id bigint, p_staff_id bigint, p_runtime_target text)
 RETURNS TABLE(ok boolean, reason text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_capabilities record;
  v_is_zalo boolean;
  v_is_web boolean;
  v_is_server boolean;
  v_zalo_web_max integer;
  v_facebook_max integer;
  v_max integer;
  v_running bigint;
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN RAISE EXCEPTION 'Campaign, account and staff IDs must be positive integers'; END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;

  SELECT staff.organization_id, staff.max_running_zalo_web_accounts, staff.max_running_facebook_accounts
  INTO v_organization_id, v_zalo_web_max, v_facebook_max
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN; END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(v_organization_id);

  -- Serialize only admission, never the duration of a campaign. Staff SHARE
  -- above also fences settings SAVE's staff UPDATE lock. Keep this before
  -- campaign/account row locks and after the existing entitlement barrier.
  IF v_runtime_target = 'desktop' AND (v_zalo_web_max IS NOT NULL OR v_facebook_max IS NOT NULL) THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('aka-agent-browser-run-limits:' || p_staff_id::text, 0));
  END IF;

  -- Server hard-end cleanup must start before the ordinary campaign/account
  -- claim locks. Candidate discovery uses only caller-readable campaign and
  -- account rows; the SECURITY DEFINER wrapper authoritatively revalidates the
  -- RPC-only Data Group source after joining the common input-first barrier.
  IF v_runtime_target = 'server'
    AND COALESCE(v_capabilities.qr_enabled, false)
    AND COALESCE(v_capabilities.server_enabled, false)
    AND EXISTS (
      SELECT 1
      FROM public.auto_campaigns AS campaign
      JOIN public.auto_accounts AS account
        ON account.id = campaign.account_id
       AND account.staff_id = campaign.staff_id
      WHERE campaign.id = p_campaign_id
        AND campaign.staff_id = p_staff_id
        AND campaign.account_id = p_account_id
        AND campaign.organization_id = v_organization_id
        AND campaign.data_target_source_mode = 'data_group'
        AND campaign.action_id IN (
          'zalo_message_phone',
          'zalo_join_group_link',
          'zalo_message_friend',
          'zalo_message_group_member',
          'zalo_message_remarketing_customer',
          'zalo_message_group',
          'zalo_add_group_member'
        )
        AND campaign.schedule_end_date IS NOT NULL
        AND campaign.schedule_end_date <= now()
        AND (
          account.organization_id IS NULL
          OR account.organization_id = v_organization_id
        )
        AND lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
        AND COALESCE(account.is_zalo_show_web, false) = false
        AND COALESCE(account.is_zalo_server, false) = true
    )
  THEN
    BEGIN
      PERFORM public.aka_agent_finalize_zalo_server_data_group_campaign(
        p_staff_id,
        v_organization_id,
        v_capabilities.capability_revision,
        p_campaign_id,
        'Chiến dịch đã hết hạn'
      );
    EXCEPTION
      -- The source, campaign or account subtype can change after optimistic
      -- candidate discovery. Those expected races are a rejected
      -- claim, not a scheduler error; the authoritative sweep handles any
      -- remaining hard-end cleanup on its next pass.
      WHEN raise_exception THEN
        IF SQLERRM NOT IN (
          'data_group_server_campaign_not_found',
          'data_group_server_runtime_not_owner'
        ) THEN
          RAISE;
        END IF;
    END;
    RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN;
  END IF;

  SELECT campaign.* INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.account_id = p_account_id
  FOR UPDATE OF campaign;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN; END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id AND account.staff_id = p_staff_id
  FOR UPDATE OF account;
  IF NOT FOUND THEN RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN; END IF;

  -- V387: old/ordinary clients cannot claim a random account. The wrapper's
  -- transaction-local turn ID must name the first pending turn of this day.
  IF v_account.flatform_type='facebook' AND v_account.facebook_random_run_enabled THEN
    IF NOT private.facebook_random_claim_allowed(p_campaign_id,p_account_id,current_setting('aka.facebook_random_turn',true)) THEN RETURN QUERY SELECT false,'random_context_required'::text; RETURN; END IF;
  ELSIF nullif(current_setting('aka.facebook_random_turn',true),'') IS NOT NULL THEN
    RETURN QUERY SELECT false,'random_mode_changed'::text; RETURN;
  END IF;

  v_is_zalo := lower(btrim(COALESCE(v_account.flatform_type, ''))) = 'zalo';
  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);

  IF v_runtime_target = 'server' THEN
    IF NOT v_is_zalo OR v_is_web OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    THEN RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN; END IF;
  ELSIF v_is_zalo AND (
    v_is_server
    OR (v_is_web AND NOT COALESCE(v_capabilities.web_enabled, false))
    OR (NOT v_is_web AND NOT v_is_server
      AND NOT COALESCE(v_capabilities.qr_enabled, false))
  ) THEN RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN; END IF;

  IF NOT private.campaign_dispatch_schedule_allowed(
    v_campaign.schedule, v_campaign.data_target_source_mode,
    v_campaign.schedule_end_date, v_campaign.daily_stop_time, now(), true
  ) THEN
    -- Shared with random planning; retain the legacy cutoff contract and locks.
    -- The tenant sweep, not this eligibility check, finalizes hard-ended sources.
    RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN;
  END IF;

  IF COALESCE(v_campaign.is_delete, false)
    OR v_campaign.status <> 'chờ xử lý'
    OR COALESCE(v_campaign.provisioning_state, 'ready') <> 'ready'
    OR (
      v_campaign.data_target_source_mode = 'data_group'
      AND NOT EXISTS (
        SELECT 1
        FROM public.auto_campaign_input_data AS input_data
        WHERE input_data.campaign_id = v_campaign.id
          AND COALESCE(input_data.is_delete, false) = false
          AND input_data.status = 'chờ xử lý'
          AND (input_data.schedule IS NULL OR input_data.schedule <= now())
      )
    )
    OR COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR v_account.status <> 'chờ xử lý'
    OR v_account.login_status <> 'đã đăng nhập'
  THEN RETURN QUERY SELECT false, 'claim_rejected'::text; RETURN; END IF;

  v_max := CASE
    WHEN lower(btrim(COALESCE(v_account.flatform_type, ''))) = 'facebook' THEN v_facebook_max
    WHEN v_is_zalo AND v_is_web AND NOT v_is_server THEN v_zalo_web_max
    ELSE NULL END;
  IF v_runtime_target = 'desktop' AND v_max IS NOT NULL THEN
    -- Status is enough for legacy clients; immutable claim/unit metadata also
    -- keeps a paused or draining run counted until its existing cleanup wins.
    -- Never filter live ownership by login/active/deleted flags. Account-only
    -- operations (login, scans) do not create a campaign and consume no slot.
    SELECT count(DISTINCT campaign.account_id) INTO v_running
    FROM public.auto_campaigns AS campaign
    JOIN public.auto_accounts AS account ON account.id = campaign.account_id
      AND account.staff_id = campaign.staff_id
    WHERE campaign.staff_id = p_staff_id
      AND account.id <> p_account_id
      AND (campaign.organization_id IS NULL OR campaign.organization_id = v_organization_id)
      AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
      AND (campaign.status = 'đang chạy' OR campaign.runtime_claim_token IS NOT NULL OR campaign.runtime_unit_token IS NOT NULL)
      AND CASE WHEN v_is_zalo THEN
        lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
          AND account.is_zalo_show_web = true AND account.is_zalo_server = false
        ELSE lower(btrim(COALESCE(account.flatform_type, ''))) = 'facebook' END;
    IF v_running >= v_max THEN
      RETURN QUERY SELECT false, 'concurrency_limit_reached'::text; RETURN;
    END IF;
  END IF;

  UPDATE public.auto_campaigns
  SET status = 'đang chạy', note = NULL, updated_at = now()
  WHERE id = p_campaign_id;
  UPDATE public.auto_accounts
  SET status = 'đang chạy', updated_at = now()
  WHERE id = p_account_id;
  RETURN QUERY SELECT true, 'claimed'::text; RETURN;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_create_data_group_v2_internal(p_staff_id bigint, p_organization_id bigint, p_name text, p_color text, p_request_id text, p_data_type_category_item_id bigint, p_bound_zalo_account_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_request_hash text;
  v_result jsonb;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  IF length(btrim(COALESCE(p_name, ''))) NOT BETWEEN 1 AND 255
    OR length(btrim(COALESCE(p_color, '#2563EB'))) NOT BETWEEN 1 AND 64
  THEN
    RAISE EXCEPTION 'invalid_data_group_payload';
  END IF;
  IF p_data_type_category_item_id IS NOT NULL
    AND NOT public.aka_agent_is_data_type_category_item(
      p_data_type_category_item_id, true
    )
  THEN
    RAISE EXCEPTION 'invalid_data_type_category_item';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'create_group',
    'name', btrim(p_name),
    'color', btrim(COALESCE(p_color, '#2563EB')),
    'dataTypeCategoryItemId', p_data_type_category_item_id,
    'boundZaloAccountId',p_bound_zalo_account_id
  )::text);

  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NOT NULL THEN
    INSERT INTO public.auto_data_ingest_batches (
      request_id, operation, request_hash, status,
      staff_id, organization_id
    ) VALUES (
      btrim(p_request_id), 'create_group', v_request_hash, 'processing',
      p_staff_id, p_organization_id
    )
    ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
    RETURNING * INTO v_batch;

    IF NOT FOUND THEN
      SELECT *
      INTO v_batch
      FROM public.auto_data_ingest_batches AS batch
      WHERE batch.staff_id = p_staff_id
        AND batch.organization_id = p_organization_id
        AND batch.request_id = btrim(p_request_id)
      FOR UPDATE;
      IF v_batch.operation <> 'create_group'
        OR v_batch.request_hash <> v_request_hash
      THEN
        RAISE EXCEPTION 'data_group_request_id_conflict';
      END IF;
      IF v_batch.result IS NOT NULL THEN
        RETURN v_batch.result;
      END IF;
      RAISE EXCEPTION 'data_group_request_incomplete';
    END IF;
  END IF;

  INSERT INTO public.auto_account_contact_groups (
    account_id, contact_type, name, purpose, color, sort_order, revision,
    data_type_category_item_id, bound_zalo_account_id, dataset_sync_mode, dataset_sync_key,
    is_delete, staff_id, organization_id
  ) VALUES (
    NULL, NULL, btrim(p_name), 'data_group',
    btrim(COALESCE(p_color, '#2563EB')),
    COALESCE((
      SELECT max(contact_group.sort_order) + 1
      FROM public.auto_account_contact_groups AS contact_group
      WHERE contact_group.staff_id = p_staff_id
        AND contact_group.organization_id = p_organization_id
        AND contact_group.purpose = 'data_group'
        AND contact_group.is_delete = false
    ), 0),
    0, p_data_type_category_item_id, p_bound_zalo_account_id, 'manual', NULL,
    false, p_staff_id, p_organization_id
  )
  RETURNING * INTO v_group;

  v_result := to_jsonb(v_group)
    || public.aka_agent_data_type_json(v_group.data_type_category_item_id)
    || jsonb_build_object('active_membership_count', 0);

  IF v_batch.id IS NOT NULL THEN
    UPDATE public.auto_data_ingest_batches
    SET group_id = v_group.id,
        status = 'completed',
        result = v_result,
        updated_at = clock_timestamp()
    WHERE id = v_batch.id;
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_current_data_type_category_item_id()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_value text := NULLIF(
    current_setting('aka_agent.data_type_category_item_id', true),
    ''
  );
BEGIN
  IF v_value IS NULL THEN
    RETURN NULL;
  END IF;
  IF lower(v_value) = 'null' THEN
    RETURN NULL;
  END IF;
  IF v_value !~ '^[1-9][0-9]*$' THEN
    RAISE EXCEPTION 'invalid_data_type_category_context';
  END IF;
  RETURN v_value::bigint;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_data_group_account_options_internal(p_group auto_account_contact_groups, p_account_ids bigint[] DEFAULT NULL::bigint[])
 RETURNS TABLE(account_id bigint, account_name text, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_type text; v_total bigint; v_counts jsonb; v_sources bigint[]; v_datasets bigint;
  v_rules jsonb; v_rule jsonb; v_account record; v_bad bigint;
BEGIN
  SELECT code INTO v_type FROM public.category_item WHERE id=p_group.data_type_category_item_id;
  -- Count eligible members by account once, rather than scanning the group per option.
  WITH member_counts AS (
    SELECT c.account_id,
      c.staff_id=p_group.staff_id AND c.organization_id=p_group.organization_id
      AND NOT EXISTS (SELECT 1 FROM public.auto_account_contact_group_member_origins o
        WHERE o.membership_id=m.id AND o.is_current AND o.source_account_id IS DISTINCT FROM c.account_id) AS compatible,
      count(*) AS n
    FROM public.auto_account_contact_group_members m
    JOIN public.auto_account_contacts c ON c.id=m.contact_id
    WHERE m.group_id=p_group.id AND NOT m.is_delete
    GROUP BY c.account_id, compatible
  )
  SELECT COALESCE(sum(mc.n),0), COALESCE(jsonb_object_agg(mc.account_id::text,mc.n)
    FILTER (WHERE mc.account_id IS NOT NULL AND mc.compatible),'{}'::jsonb)
  INTO v_total,v_counts FROM member_counts mc;

  -- A live dataset remains a source even when its current snapshot is empty.
  WITH datasets AS (
    SELECT d.id,d.account_id FROM public.auto_account_contacts_dataset d
    WHERE d.auto_data_group_id=p_group.id AND NOT d.is_delete
    UNION
    SELECT d.id,d.account_id FROM public.auto_account_contacts_dataset d
    WHERE d.group_id=p_group.id AND NOT d.is_delete
  ), sources AS (
    SELECT d.account_id FROM datasets d
    UNION ALL
    SELECT c.account_id FROM public.auto_automation a
    LEFT JOIN public.auto_campaigns c ON c.id=a.source_campaign_id
    WHERE a.target_data_group_id=p_group.id AND a.is_active AND NOT a.is_delete
  )
  SELECT (SELECT count(*) FROM datasets),array_agg(DISTINCT s.account_id)
  INTO v_datasets,v_sources FROM sources s;

  SELECT COALESCE(jsonb_agg(to_jsonb(r)||jsonb_build_object('field_code',f.code)),'[]'::jsonb)
  INTO v_rules FROM public.auto_account_contact_group_dynamic_filters d
  JOIN public.auto_account_contact_group_dynamic_filter_rules r ON r.dynamic_filter_id=d.id
  JOIN public.category_item f ON f.id=r.field_category_item_id WHERE d.group_id=p_group.id;

  FOR v_account IN
    SELECT NULL::bigint id, 'Không gắn tài khoản'::text name
    UNION ALL
    SELECT a.id,a.name FROM public.auto_accounts a
    WHERE a.staff_id=p_group.staff_id AND a.organization_id=p_group.organization_id
      AND a.flatform_type='zalo' AND (NOT a.is_delete OR a.id=p_group.bound_zalo_account_id)
      AND (p_account_ids IS NULL OR a.id=ANY(p_account_ids))
    ORDER BY id NULLS FIRST
  LOOP
    account_id:=v_account.id; account_name:=v_account.name; reason:=NULL;
    IF account_id IS NOT NULL THEN
      IF p_group.purpose<>'data_group' OR v_type IS NULL OR v_type NOT IN ('zalo_person','zalo_group') THEN
        reason:='data_group_bound_type_invalid';
      ELSIF NOT public.aka_agent_data_group_account_available(account_id,p_group.staff_id,p_group.organization_id) THEN
        reason:='data_group_bound_account_invalid';
      ELSIF p_group.dataset_sync_mode='dataset_auto' AND v_datasets=0 THEN
        reason:='data_group_bound_source_unknown';
      ELSIF EXISTS(SELECT 1 FROM unnest(v_sources) s(id) WHERE s.id IS DISTINCT FROM account_id) THEN
        reason:='data_group_bound_source_mismatch';
      ELSE
        v_bad:=v_total-COALESCE((v_counts->>account_id::text)::bigint,0);
        IF v_bad>0 THEN
          reason:='data_group_bound_members_mismatch:'||v_bad::text;
        ELSE
          FOR v_rule IN SELECT value FROM jsonb_array_elements(v_rules) LOOP
            BEGIN
              PERFORM public.aka_agent_data_group_validate_bound_rule(account_id,p_group.staff_id,p_group.organization_id,v_rule);
            EXCEPTION WHEN SQLSTATE 'P0001' THEN
              IF SQLERRM<>'data_group_bound_rule_mismatch' THEN RAISE; END IF;
              reason:='data_group_bound_rule_mismatch';
            END;
            EXIT WHEN reason IS NOT NULL;
          END LOOP;
        END IF;
      END IF;
    END IF;
    RETURN NEXT;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_data_group_validate_bound_rule(p_account_id bigint, p_staff_id bigint, p_organization_id bigint, p_rule jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_key text; v_raw text; v_field text := p_rule->>'field_code';
BEGIN
  IF p_account_id IS NULL THEN RETURN; END IF;
  IF NULLIF(p_rule->>'account_id','')::bigint IS NOT NULL AND (p_rule->>'account_id')::bigint <> p_account_id THEN
    RAISE EXCEPTION 'data_group_bound_rule_mismatch';
  END IF;
  FOR v_key IN SELECT jsonb_array_elements_text(COALESCE(p_rule->'value_keys','[]'::jsonb)) LOOP
    v_raw := v_key;
    IF v_field IN ('zalo_tag','zalo_group_membership') AND position(':' IN v_key)>0 THEN
      IF split_part(v_key,':',1) <> p_account_id::text THEN RAISE EXCEPTION 'data_group_bound_rule_mismatch'; END IF;
      v_raw := substring(v_key FROM position(':' IN v_key)+1);
    END IF;
    IF v_field='akabiz_tag' AND NOT EXISTS (
      SELECT 1 FROM public.auto_contact_tags t WHERE t.id::text=v_raw AND t.staff_id=p_staff_id
        AND t.organization_id=p_organization_id AND NOT t.is_delete AND (t.auto_account_id IS NULL OR t.auto_account_id=p_account_id)
    ) THEN RAISE EXCEPTION 'data_group_bound_rule_mismatch'; END IF;
    IF v_field='zalo_tag' AND NOT EXISTS (
      SELECT 1 FROM public.chat_zalo_account_tag t JOIN public.chat_zalo_account_organization b ON b.chat_zalo_account_id=t.chat_zalo_account_id
      WHERE b.auto_account_id=p_account_id AND b.organization_id=p_organization_id AND b.is_active AND t.zalo_id=v_raw
      UNION ALL
      SELECT 1 FROM public.auto_account_contacts c WHERE c.account_id=p_account_id AND c.staff_id=p_staff_id
        AND c.organization_id=p_organization_id AND c.contact_type='zalo_tag' AND NOT c.is_delete AND c.uid=v_raw
    ) THEN RAISE EXCEPTION 'data_group_bound_rule_mismatch'; END IF;
    IF v_field='zalo_group_membership' AND NOT EXISTS (
      SELECT 1 FROM public.zalo_groups g WHERE g.account_id=p_account_id AND g.staff_id=p_staff_id
        AND g.organization_id=p_organization_id AND g.zalo_group_id=v_raw
    ) THEN RAISE EXCEPTION 'data_group_bound_rule_mismatch'; END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_delete_data_group(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_count integer := 0;
  v_result jsonb;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_request_hash text := md5('delete_group:' || COALESCE(p_group_id, 0)::text);
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);

  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NOT NULL THEN
    INSERT INTO public.auto_data_ingest_batches (
      request_id, operation, group_id, request_hash, status, staff_id, organization_id
    ) VALUES (
      btrim(p_request_id), 'delete_group', p_group_id, v_request_hash, 'processing',
      p_staff_id, p_organization_id
    )
    ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
    RETURNING * INTO v_batch;
    IF NOT FOUND THEN
      SELECT * INTO v_batch
      FROM public.auto_data_ingest_batches
      WHERE staff_id = p_staff_id AND organization_id = p_organization_id
        AND request_id = btrim(p_request_id)
      FOR UPDATE;
      IF v_batch.operation <> 'delete_group' OR v_batch.request_hash <> v_request_hash THEN
        RAISE EXCEPTION 'data_group_request_id_conflict';
      END IF;
      IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
      RAISE EXCEPTION 'data_group_request_incomplete';
    END IF;
  END IF;

  SELECT * INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  IF v_group.is_delete THEN
    v_result := jsonb_build_object(
      'success', true, 'count', 0, 'group_revision', v_group.revision
    );
  ELSE
    UPDATE public.auto_account_contact_groups
    SET is_delete = true, revision = revision + 1, updated_at = now()
    WHERE id = v_group.id
    RETURNING * INTO v_group;

    UPDATE public.auto_account_contact_group_members
    SET is_delete = true,
        change_revision = v_group.revision,
        updated_at = now()
    WHERE group_id = v_group.id AND is_delete = false;
    GET DIAGNOSTICS v_count = ROW_COUNT;

    UPDATE public.auto_account_contact_group_member_origins AS origin
    SET is_current = false, updated_at = now()
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id
      AND origin.membership_id = member.id
      AND origin.is_current = true;

    UPDATE public.auto_campaign_data_group_sources
    SET status = 'stopped', stopped_at = now(), stop_reason = 'group_deleted', updated_at = now()
    WHERE group_id = v_group.id AND status IN ('baselining', 'active');

    v_result := jsonb_build_object(
      'success', true, 'count', v_count, 'group_revision', v_group.revision
    );
  END IF;

  IF v_batch.id IS NOT NULL THEN
    UPDATE public.auto_data_ingest_batches
    SET status = 'completed', result = v_result, updated_at = now()
    WHERE id = v_batch.id;
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_ingest_data_group_v186_internal(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_group_id bigint, p_kind text, p_rows jsonb, p_dataset_id bigint DEFAULT NULL::bigint, p_dataset_name text DEFAULT NULL::text, p_import_source text DEFAULT NULL::text, p_source_account_id bigint DEFAULT NULL::bigint, p_source_name text DEFAULT NULL::text, p_payload_hash text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_dataset public.auto_account_contacts_dataset%ROWTYPE;
  v_source_account public.auto_accounts%ROWTYPE;
  v_contact public.auto_account_contacts%ROWTYPE;
  v_member public.auto_account_contact_group_members%ROWTYPE;
  v_row record;
  v_source record;
  v_raw_account_id text;
  v_raw_contact_id text;
  v_raw_automation_detail_id text;
  v_origin_automation_detail_id bigint;
  v_row_account_id bigint;
  v_contact_type text;
  v_platform text;
  v_name text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_extra jsonb;
  v_dataset_contact_type text;
  v_dataset_platform text;
  v_dataset_source_key text;
  v_dataset_display_name text;
  v_duplicate_in_batch boolean := false;
  v_duplicate_conflict boolean := false;
  v_member_found boolean := false;
  v_batch_seen jsonb := '{}'::jsonb;
  v_first_payload jsonb;
  v_current_payload jsonb;
  v_request_hash text;
  v_revision bigint;
  v_revision_started boolean := false;
  v_inserted_members integer := 0;
  v_reactivated_members integer := 0;
  v_existing_members integer := 0;
  v_removed_members integer := 0;
  v_inserted_inputs integer := 0;
  v_existing_inputs integer := 0;
  v_incompatible integer := 0;
  v_conflict integer := 0;
  v_invalid integer := 0;
  v_conflicts jsonb := '[]'::jsonb;
  v_outcome jsonb;
  v_result jsonb;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(p_staff_id, p_organization_id);
  IF NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
    OR p_kind NOT IN ('manual', 'upload', 'scan', 'automation', 'api', 'external_sync')
    OR jsonb_typeof(COALESCE(p_rows, 'null'::jsonb)) <> 'array'
    OR jsonb_array_length(p_rows) > 10000
    OR (p_import_source IS NOT NULL AND p_import_source NOT IN ('textbox', 'image', 'sheet', 'excel'))
  THEN
    RAISE EXCEPTION 'invalid_data_group_ingest_payload';
  END IF;

  IF p_kind = 'external_sync' AND NOT EXISTS (
    SELECT 1 FROM public.auto_data_group_external_sync_runs r
    JOIN public.auto_data_group_external_sync_sources s ON s.id=r.source_id
    WHERE r.token::text=current_setting('aka_agent.sheet_sync_run_token',true)
      AND r.status='running' AND s.run_token=r.token AND s.revision=r.source_revision
      AND s.is_enabled AND NOT s.is_delete AND r.group_id=p_group_id
      AND r.staff_id=p_staff_id AND r.organization_id=p_organization_id
  ) THEN RAISE EXCEPTION 'sheet_sync_unclaimed'; END IF;

  SELECT * INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  IF p_source_account_id IS NOT NULL THEN
    SELECT * INTO v_source_account
    FROM public.auto_accounts AS account
    WHERE account.id = p_source_account_id
      AND account.staff_id = p_staff_id
      AND (account.organization_id IS NULL OR account.organization_id = p_organization_id);
    IF NOT FOUND THEN RAISE EXCEPTION 'data_group_source_account_not_found'; END IF;
  END IF;

  IF v_group.bound_zalo_account_id IS NOT NULL THEN
    IF NOT public.aka_agent_data_group_account_available(v_group.bound_zalo_account_id,p_staff_id,p_organization_id) THEN RAISE EXCEPTION 'data_group_bound_account_invalid'; END IF;
    IF (p_source_account_id IS NOT NULL AND p_source_account_id<>v_group.bound_zalo_account_id)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) r WHERE NULLIF(r->>'source_account_id','') IS NOT NULL AND r->>'source_account_id'<>v_group.bound_zalo_account_id::text)
      OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) r LEFT JOIN public.auto_account_contacts c ON c.id::text=r->>'contact_id'
        WHERE NULLIF(r->>'contact_id','') IS NOT NULL AND (c.id IS NULL OR c.account_id IS DISTINCT FROM v_group.bound_zalo_account_id OR c.staff_id IS DISTINCT FROM p_staff_id OR c.organization_id IS DISTINCT FROM p_organization_id))
      OR (p_dataset_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.auto_account_contacts_dataset d WHERE d.id=p_dataset_id AND d.account_id IS DISTINCT FROM v_group.bound_zalo_account_id))
    THEN RAISE EXCEPTION 'data_group_bound_source_mismatch'; END IF;
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'ingest', 'groupId', p_group_id, 'kind', p_kind,
    'rows', p_rows, 'datasetId', p_dataset_id, 'datasetName', p_dataset_name,
    'importSource', p_import_source, 'sourceAccountId', p_source_account_id,
    'sourceName', p_source_name
  )::text);

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, kind, dataset_id, source_account_id,
    source_name, client_payload_hash, request_hash, status,
    staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'ingest', p_group_id, p_kind, p_dataset_id,
    p_source_account_id, NULLIF(btrim(COALESCE(p_source_name, '')), ''),
    NULLIF(btrim(COALESCE(p_payload_hash, '')), ''), v_request_hash, 'processing',
    p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT * INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'ingest' OR v_batch.group_id IS DISTINCT FROM p_group_id
      OR v_batch.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  p_source_account_id := COALESCE(p_source_account_id,v_group.bound_zalo_account_id);
  IF p_source_account_id IS NOT NULL THEN SELECT * INTO v_source_account FROM public.auto_accounts WHERE id=p_source_account_id; END IF;
  IF p_kind = 'upload' THEN
    v_dataset_display_name := COALESCE(
      NULLIF(btrim(COALESCE(p_dataset_name, '')), ''),
      NULLIF(btrim(COALESCE(p_source_name, '')), ''),
      v_group.name
    );
    IF length(v_dataset_display_name) > 255 THEN
      RAISE EXCEPTION 'invalid_data_group_dataset_name';
    END IF;
    -- The explicit dataset name is the logical identity.  When absent, the
    -- source filename/name becomes that identity. A changed physical filename
    -- therefore still refreshes the same named dataset.
    v_dataset_source_key := 'upload:'
      || lower(regexp_replace(v_dataset_display_name, '[[:space:]]+', ' ', 'g'));

    WITH row_types AS (
      SELECT DISTINCT lower(btrim(item.value ->> 'contact_type')) AS value
      FROM jsonb_array_elements(p_rows) AS item(value)
      WHERE jsonb_typeof(item.value) = 'object'
        AND lower(btrim(COALESCE(item.value ->> 'contact_type', ''))) IN (
          'person', 'group', 'page', 'page_inbox_customer', 'zalo_tag',
          'phone', 'email', 'campaign_input'
        )
    )
    SELECT CASE WHEN count(*) = 1 THEN min(value) ELSE 'campaign_input' END
    INTO v_dataset_contact_type
    FROM row_types;

    WITH row_platforms AS (
      SELECT DISTINCT lower(btrim(COALESCE(
        NULLIF(item.value ->> 'flatform_type', ''),
        v_source_account.flatform_type,
        CASE WHEN lower(btrim(item.value ->> 'contact_type')) = 'email' THEN 'email' END,
        ''
      ))) AS value
      FROM jsonb_array_elements(p_rows) AS item(value)
      WHERE jsonb_typeof(item.value) = 'object'
    ), valid_platforms AS (
      SELECT value FROM row_platforms
      WHERE value IN ('facebook', 'zalo', 'email', 'sms')
    )
    SELECT CASE WHEN count(*) = 1 THEN min(value) ELSE 'mixed' END
    INTO v_dataset_platform
    FROM valid_platforms;
  END IF;

  IF p_dataset_id IS NOT NULL THEN
    SELECT * INTO v_dataset
    FROM public.auto_account_contacts_dataset AS dataset
    WHERE dataset.id = p_dataset_id
      AND dataset.staff_id = p_staff_id
      AND dataset.organization_id = p_organization_id
      AND dataset.is_delete = false;
    IF NOT FOUND THEN RAISE EXCEPTION 'data_group_dataset_not_found'; END IF;
    IF p_kind = 'upload' AND (
      v_dataset.source <> 'upload' OR v_dataset.group_id IS DISTINCT FROM v_group.id
    ) THEN
      RAISE EXCEPTION 'data_group_upload_dataset_mismatch';
    END IF;
    IF p_kind = 'upload' THEN
      UPDATE public.auto_account_contacts_dataset_members
      SET is_current = false, updated_at = now()
      WHERE dataset_id = v_dataset.id AND is_current = true;
      UPDATE public.auto_account_contact_group_member_origins
      SET is_current = false, updated_at = now()
      WHERE dataset_id = v_dataset.id AND is_current = true;
    END IF;
  ELSIF p_kind = 'upload' THEN
    INSERT INTO public.auto_account_contacts_dataset (
      name, link, description, source, account_id, group_id, flatform_type,
      contact_type, scan_type, source_key, last_scanned_at, last_scan_status,
      extra_data, contact_count, is_delete, staff_id, organization_id
    ) VALUES (
      v_dataset_display_name,
      NULL, NULL, 'upload', p_source_account_id, v_group.id,
      COALESCE(v_dataset_platform, 'mixed'),
      COALESCE(v_dataset_contact_type, 'campaign_input'),
      'upload_data', v_dataset_source_key, now(), 'completed',
      jsonb_strip_nulls(jsonb_build_object(
        'importSource', p_import_source, 'requestId', btrim(p_request_id)
      )),
      0, false, p_staff_id, p_organization_id
    )
    ON CONFLICT (
      staff_id, organization_id, group_id, COALESCE(account_id, 0::bigint),
      flatform_type, contact_type, scan_type, lower(btrim(source_key))
    )
      WHERE is_delete = false AND source = 'upload' AND group_id IS NOT NULL
    DO UPDATE SET
      name = EXCLUDED.name,
      extra_data = COALESCE(auto_account_contacts_dataset.extra_data, '{}'::jsonb)
        || EXCLUDED.extra_data,
      updated_at = now(), last_scanned_at = now(), last_scan_status = 'completed'
    RETURNING * INTO v_dataset;

    -- Re-import refreshes one logical dataset snapshot. Historical batch and
    -- origin rows remain, but only incoming contacts are current afterward.
    UPDATE public.auto_account_contacts_dataset_members
    SET is_current = false, updated_at = now()
    WHERE dataset_id = v_dataset.id AND is_current = true;
    UPDATE public.auto_account_contact_group_member_origins
    SET is_current = false, updated_at = now()
    WHERE dataset_id = v_dataset.id AND is_current = true;

    UPDATE public.auto_data_ingest_batches
    SET dataset_id = v_dataset.id, updated_at = now()
    WHERE id = v_batch.id;
  END IF;

  FOR v_row IN
    SELECT item.value AS payload, item.ordinality::integer AS row_index
    FROM jsonb_array_elements(p_rows) WITH ORDINALITY AS item(value, ordinality)
  LOOP
    v_duplicate_in_batch := false;
    v_duplicate_conflict := false;
    v_member_found := false;
    v_origin_automation_detail_id := NULL;
    v_contact_type := NULL;
    v_platform := NULL;
    v_name := NULL;
    v_uid := NULL;
    v_url := NULL;
    v_phone := NULL;
    v_email := NULL;
    v_extra := '{}'::jsonb;
    IF jsonb_typeof(v_row.payload) <> 'object' THEN
      v_invalid := v_invalid + 1;
      CONTINUE;
    END IF;

    v_raw_account_id := NULLIF(btrim(COALESCE(v_row.payload ->> 'source_account_id', '')), '');
    IF v_raw_account_id IS NOT NULL AND v_raw_account_id !~ '^[1-9][0-9]{0,17}$' THEN
      v_invalid := v_invalid + 1;
      CONTINUE;
    END IF;
    v_row_account_id := COALESCE(
      CASE WHEN v_raw_account_id IS NULL THEN NULL ELSE v_raw_account_id::bigint END,
      p_source_account_id
    );
    v_contact := NULL;

    v_raw_contact_id := NULLIF(btrim(COALESCE(v_row.payload ->> 'contact_id', '')), '');
    IF v_raw_contact_id IS NOT NULL AND v_raw_contact_id !~ '^[1-9][0-9]{0,17}$' THEN
      v_invalid := v_invalid + 1;
      CONTINUE;
    END IF;
    IF v_raw_contact_id IS NOT NULL THEN
      SELECT * INTO v_contact
      FROM public.auto_account_contacts AS contact
      WHERE contact.id = v_raw_contact_id::bigint
        AND contact.staff_id = p_staff_id
        AND contact.organization_id = p_organization_id
      FOR UPDATE;
      IF NOT FOUND OR (
        v_row_account_id IS NOT NULL
        AND v_contact.account_id IS DISTINCT FROM v_row_account_id
      ) THEN
        v_invalid := v_invalid + 1;
        CONTINUE;
      END IF;
      v_row_account_id := COALESCE(v_row_account_id, v_contact.account_id);
      -- Selecting an existing source contact only changes group membership;
      -- it must never resurrect the source contact's own lifecycle flag.
      v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
      v_platform := NULLIF(lower(btrim(COALESCE(v_contact.flatform_type, ''))), '');
      v_name := NULLIF(btrim(COALESCE(v_contact.name, '')), '');
      v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
      v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
      v_phone := NULLIF(public.aka_agent_internal_normalize_phone(COALESCE(
        NULLIF(v_contact.phone, ''), NULLIF(v_contact.extra_data ->> 'phone', ''),
        CASE WHEN v_contact.contact_type = 'phone' THEN v_contact.uid END, ''
      )), '');
      v_email := NULLIF(lower(btrim(COALESCE(
        NULLIF(v_contact.email, ''), NULLIF(v_contact.extra_data ->> 'email', ''),
        CASE WHEN v_contact.contact_type = 'email' THEN v_contact.uid END, ''
      ))), '');
      v_extra := COALESCE(v_contact.extra_data, '{}'::jsonb);
    ELSE
      v_contact_type := lower(btrim(COALESCE(v_row.payload ->> 'contact_type', '')));
      IF v_contact_type NOT IN (
        'person', 'group', 'page', 'page_inbox_customer', 'zalo_tag',
        'phone', 'email', 'campaign_input'
      ) THEN
        v_invalid := v_invalid + 1;
        CONTINUE;
      END IF;

      IF v_row_account_id IS NOT NULL THEN
        SELECT * INTO v_source_account
        FROM public.auto_accounts AS account
        WHERE account.id = v_row_account_id
          AND account.staff_id = p_staff_id
          AND (account.organization_id IS NULL OR account.organization_id = p_organization_id);
        IF NOT FOUND THEN
          v_invalid := v_invalid + 1;
          CONTINUE;
        END IF;
      ELSE
        v_source_account := NULL;
      END IF;

      v_platform := NULLIF(lower(btrim(COALESCE(
        NULLIF(v_row.payload ->> 'flatform_type', ''),
        v_source_account.flatform_type,
        CASE WHEN v_contact_type = 'email' THEN 'email' ELSE NULL END,
        ''
      ))), '');
      -- Accountless phone/email rows are deliberately platform-neutral.  A
      -- campaign decides portability from the validated value, not this label.
      IF (v_platform IS NULL AND v_contact_type NOT IN ('phone', 'email'))
        OR (v_platform IS NOT NULL AND v_platform NOT IN ('facebook', 'zalo', 'email', 'sms'))
      THEN
        v_invalid := v_invalid + 1;
        CONTINUE;
      END IF;

      v_phone := public.aka_agent_internal_normalize_phone(COALESCE(
        NULLIF(v_row.payload ->> 'phone', ''),
        CASE WHEN v_contact_type = 'phone' THEN v_row.payload ->> 'uid' ELSE NULL END,
        ''
      ));
      v_phone := NULLIF(v_phone, '');
      v_email := NULLIF(lower(btrim(COALESCE(
        NULLIF(v_row.payload ->> 'email', ''),
        CASE WHEN v_contact_type = 'email' THEN v_row.payload ->> 'uid' ELSE NULL END,
        ''
      ))), '');
      IF v_email IS NOT NULL AND (v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
          OR length(v_email) > 254) THEN
        v_email := NULL;
      END IF;
      v_url := NULLIF(btrim(COALESCE(v_row.payload ->> 'url', '')), '');
      v_uid := CASE v_contact_type
        WHEN 'phone' THEN v_phone
        WHEN 'email' THEN v_email
        ELSE COALESCE(
          NULLIF(btrim(COALESCE(v_row.payload ->> 'uid', '')), ''),
          v_url
        )
      END;
      IF v_uid IS NULL THEN
        v_invalid := v_invalid + 1;
        CONTINUE;
      END IF;
      v_name := COALESCE(NULLIF(btrim(COALESCE(v_row.payload ->> 'name', '')), ''), v_uid);
      v_extra := COALESCE(v_row.payload -> 'extra_data', '{}'::jsonb);
      IF jsonb_typeof(v_extra) <> 'object' THEN
        v_invalid := v_invalid + 1;
        CONTINUE;
      END IF;
      v_extra := v_extra || jsonb_strip_nulls(jsonb_build_object(
        'phone', v_phone,
        'email', v_email,
        'info1', NULLIF(v_row.payload ->> 'info1', ''),
        'info2', NULLIF(v_row.payload ->> 'info2', ''),
        'info3', NULLIF(v_row.payload ->> 'info3', ''),
        'info4', NULLIF(v_row.payload ->> 'info4', ''),
        'info5', NULLIF(v_row.payload ->> 'info5', '')
      ));

      IF v_row_account_id IS NULL THEN
        -- Accountless identity is intentionally NOT global. Reuse is allowed
        -- only inside the explicitly supplied dataset; otherwise each row gets
        -- its own canonical contact and campaign delivery dedupe happens later.
        IF v_dataset.id IS NOT NULL THEN
          SELECT contact.* INTO v_contact
          FROM public.auto_account_contacts_dataset_members AS dataset_member
          JOIN public.auto_account_contacts AS contact ON contact.id = dataset_member.contact_id
          WHERE dataset_member.dataset_id = v_dataset.id
            AND contact.account_id IS NULL
            AND contact.staff_id = p_staff_id
            AND contact.organization_id = p_organization_id
            AND contact.flatform_type IS NOT DISTINCT FROM v_platform
            AND contact.contact_type = v_contact_type
            AND contact.uid = v_uid
          ORDER BY dataset_member.created_at, contact.id
          LIMIT 1
          FOR UPDATE OF contact;
        END IF;
        IF v_contact.id IS NULL THEN
          INSERT INTO public.auto_account_contacts (
            account_id, flatform_type, contact_type, name, uid, url, phone, email,
            extra_data, is_delete, staff_id, organization_id, updated_at
          ) VALUES (
            NULL, v_platform, v_contact_type, v_name, v_uid, v_url, v_phone, v_email,
            v_extra, false, p_staff_id, p_organization_id, now()
          ) RETURNING * INTO v_contact;
        ELSE
          UPDATE public.auto_account_contacts AS contact
          SET name = CASE
                WHEN NULLIF(btrim(contact.name), '') IS NULL OR contact.name = contact.uid
                  THEN v_name ELSE contact.name END,
              url = COALESCE(contact.url, v_url),
              phone = COALESCE(contact.phone, v_phone),
              email = COALESCE(contact.email, v_email),
              -- Existing/earlier values win; this only fills absent keys.
              extra_data = v_extra || COALESCE(contact.extra_data, '{}'::jsonb),
              is_delete = false, updated_at = now()
          WHERE contact.id = v_contact.id
          RETURNING * INTO v_contact;
        END IF;
      ELSIF p_kind = 'external_sync' THEN
        -- Preserve every existing contact field, including lifecycle flags.
        INSERT INTO public.auto_account_contacts (
          account_id, flatform_type, contact_type, name, uid, url, phone, email,
          extra_data, is_delete, staff_id, organization_id, updated_at
        ) VALUES (
          v_row_account_id, v_platform, v_contact_type, v_name, v_uid, v_url, v_phone, v_email,
          v_extra, false, p_staff_id, p_organization_id, now()
        ) ON CONFLICT (account_id, contact_type, uid) DO NOTHING RETURNING * INTO v_contact;
        IF v_contact.id IS NULL THEN
          SELECT * INTO v_contact FROM public.auto_account_contacts
          WHERE account_id=v_row_account_id AND contact_type=v_contact_type AND uid=v_uid
            AND staff_id=p_staff_id AND organization_id=p_organization_id FOR UPDATE;
          IF NOT FOUND THEN RAISE EXCEPTION 'sheet_sync_contact_conflict'; END IF;
        END IF;
      ELSE
        INSERT INTO public.auto_account_contacts AS existing_contact (
          account_id, flatform_type, contact_type, name, uid, url, phone, email,
          extra_data, is_delete, staff_id, organization_id, updated_at
        ) VALUES (
          v_row_account_id, v_platform, v_contact_type, v_name, v_uid, v_url, v_phone, v_email,
          v_extra, false, p_staff_id, p_organization_id, now()
        )
        ON CONFLICT (account_id, contact_type, uid) DO UPDATE SET
          flatform_type = COALESCE(existing_contact.flatform_type, EXCLUDED.flatform_type),
          name = CASE
            WHEN NULLIF(btrim(existing_contact.name), '') IS NULL
              OR existing_contact.name = existing_contact.uid THEN EXCLUDED.name
            ELSE existing_contact.name END,
          url = COALESCE(existing_contact.url, EXCLUDED.url),
          phone = COALESCE(existing_contact.phone, EXCLUDED.phone),
          email = COALESCE(existing_contact.email, EXCLUDED.email),
          -- First persisted value wins; later duplicates only fill missing keys.
          extra_data = EXCLUDED.extra_data || COALESCE(existing_contact.extra_data, '{}'::jsonb),
          is_delete = false,
          staff_id = EXCLUDED.staff_id,
          organization_id = EXCLUDED.organization_id,
          updated_at = now()
        RETURNING * INTO v_contact;
      END IF;
    END IF;

    IF p_kind = 'external_sync' AND v_contact.is_delete THEN
      v_invalid := v_invalid + 1;
      CONTINUE;
    END IF;

    SELECT * INTO v_member
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id AND member.contact_id = v_contact.id
    FOR UPDATE;
    v_member_found := FOUND;
    v_current_payload := jsonb_strip_nulls(jsonb_build_object(
      'name', NULLIF(btrim(COALESCE(v_row.payload ->> 'name', '')), ''),
      'uid', NULLIF(btrim(COALESCE(v_row.payload ->> 'uid', '')), ''),
      'url', NULLIF(btrim(COALESCE(v_row.payload ->> 'url', '')), ''),
      'phone', NULLIF(public.aka_agent_internal_normalize_phone(
        COALESCE(v_row.payload ->> 'phone', '')
      ), ''),
      'email', NULLIF(lower(btrim(COALESCE(v_row.payload ->> 'email', ''))), ''),
      'info1', NULLIF(v_row.payload ->> 'info1', ''),
      'info2', NULLIF(v_row.payload ->> 'info2', ''),
      'info3', NULLIF(v_row.payload ->> 'info3', ''),
      'info4', NULLIF(v_row.payload ->> 'info4', ''),
      'info5', NULLIF(v_row.payload ->> 'info5', ''),
      'extra_data', CASE WHEN jsonb_typeof(v_row.payload -> 'extra_data') = 'object'
        THEN v_row.payload -> 'extra_data' ELSE '{}'::jsonb END
    ));
    v_raw_automation_detail_id := NULLIF(btrim(COALESCE(
      v_row.payload -> 'extra_data' ->> 'automationDetailId',
      v_row.payload ->> 'automation_detail_id',
      ''
    )), '');
    IF p_kind = 'automation'
      AND v_raw_automation_detail_id ~ '^[1-9][0-9]{0,17}$'
    THEN
      SELECT detail.id INTO v_origin_automation_detail_id
      FROM public.auto_automation_detail AS detail
      WHERE detail.id = v_raw_automation_detail_id::bigint
        AND detail.staff_id = p_staff_id
        AND detail.organization_id = p_organization_id;
    END IF;
    v_duplicate_in_batch := v_batch_seen ? v_contact.id::text;

    IF v_duplicate_in_batch THEN
      v_first_payload := v_batch_seen -> v_contact.id::text;
      SELECT EXISTS (
        SELECT 1
        FROM jsonb_each(v_first_payload - 'extra_data') AS first_value(key, value)
        JOIN jsonb_each(v_current_payload - 'extra_data') AS current_value(key, value)
          USING (key)
        WHERE first_value.value IS DISTINCT FROM current_value.value
      ) OR EXISTS (
        SELECT 1
        FROM jsonb_each(COALESCE(v_first_payload -> 'extra_data', '{}'::jsonb))
          AS first_extra(key, value)
        JOIN jsonb_each(COALESCE(v_current_payload -> 'extra_data', '{}'::jsonb))
          AS current_extra(key, value)
          USING (key)
        WHERE first_extra.value IS DISTINCT FROM current_extra.value
      ) INTO v_duplicate_conflict;

      -- Extend the first-row snapshot only with fields it did not provide.
      v_first_payload := v_current_payload || v_first_payload;
      v_first_payload := jsonb_set(
        v_first_payload,
        '{extra_data}',
        COALESCE(v_current_payload -> 'extra_data', '{}'::jsonb)
          || COALESCE((v_batch_seen -> v_contact.id::text) -> 'extra_data', '{}'::jsonb),
        true
      );
      v_batch_seen := jsonb_set(
        v_batch_seen, ARRAY[v_contact.id::text], v_first_payload, true
      );
      IF v_duplicate_conflict THEN
        v_conflict := v_conflict + 1;
        v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
          'rowIndex', v_row.row_index - 1,
          'code', 'duplicate_identity_conflict',
          'message', 'Dòng trùng định danh có giá trị khác; giữ giá trị của dòng đầu.',
          'contactId', v_contact.id
        ));
      END IF;
    ELSE
      v_batch_seen := jsonb_set(
        v_batch_seen, ARRAY[v_contact.id::text], v_current_payload, true
      );
    END IF;

    IF NOT v_revision_started THEN
      UPDATE public.auto_account_contact_groups
      SET revision = revision + 1, updated_at = now()
      WHERE id = v_group.id
      RETURNING revision INTO v_revision;
      v_revision_started := true;
    END IF;

    IF NOT v_member_found THEN
      INSERT INTO public.auto_account_contact_group_members (
        group_id, contact_id, is_delete, change_revision, created_at, updated_at
      ) VALUES (v_group.id, v_contact.id, false, v_revision, now(), now())
      RETURNING * INTO v_member;
      v_inserted_members := v_inserted_members + 1;
    ELSIF v_duplicate_in_batch THEN
      IF NOT v_duplicate_conflict THEN
        v_existing_members := v_existing_members + 1;
      END IF;
    ELSIF v_member.is_delete THEN
      UPDATE public.auto_account_contact_group_members
      SET is_delete = false, change_revision = v_revision, updated_at = now()
      WHERE id = v_member.id
      RETURNING * INTO v_member;
      v_reactivated_members := v_reactivated_members + 1;
    ELSE
      UPDATE public.auto_account_contact_group_members
      SET change_revision = v_revision, updated_at = now()
      WHERE id = v_member.id
      RETURNING * INTO v_member;
      v_existing_members := v_existing_members + 1;
    END IF;

    INSERT INTO public.auto_account_contact_group_member_origins (
      membership_id, kind, dataset_id, batch_id, source_account_id, automation_detail_id,
      source_name_snapshot, relationship_kind, is_current, created_at, updated_at
    ) VALUES (
      v_member.id, p_kind, v_dataset.id, v_batch.id,
      COALESCE(v_row_account_id, v_contact.account_id),
      v_origin_automation_detail_id,
      COALESCE(NULLIF(btrim(COALESCE(p_source_name, '')), ''), v_source_account.name),
      public.aka_agent_validate_data_group_relationship_kind(
        v_member.id,
        COALESCE(v_row_account_id, v_contact.account_id),
        v_dataset.id,
        CASE
          WHEN jsonb_typeof(v_row.payload -> 'extra_data') = 'object'
            THEN COALESCE(
              v_row.payload -> 'extra_data' ->> 'relationshipKind',
              v_row.payload -> 'extra_data' ->> 'relationship_kind'
            )
          ELSE NULL
        END,
        CASE
          WHEN jsonb_typeof(v_row.payload -> 'extra_data') = 'object'
            THEN v_row.payload -> 'extra_data'
          ELSE '{}'::jsonb
        END
      ),
      CASE
        WHEN v_dataset.id IS NOT NULL AND v_dataset.source = 'scan' THEN EXISTS (
          SELECT 1 FROM public.auto_account_contacts_dataset_members AS dataset_member
          WHERE dataset_member.dataset_id = v_dataset.id
            AND dataset_member.contact_id = v_contact.id
            AND dataset_member.is_current = true
        )
        ELSE true
      END,
      now(), now()
    )
    ON CONFLICT DO NOTHING;

    IF v_dataset.id IS NOT NULL AND v_dataset.source = 'upload' AND v_dataset.group_id = v_group.id THEN
      INSERT INTO public.auto_account_contacts_dataset_members (
        dataset_id, contact_id, sort_order, is_current,
        first_seen_at, last_seen_at, created_at, updated_at
      ) VALUES (
        v_dataset.id, v_contact.id, GREATEST(v_row.row_index - 1, 0), true,
        now(), now(), now(), now()
      )
      ON CONFLICT (dataset_id, contact_id) DO UPDATE SET
        sort_order = LEAST(auto_account_contacts_dataset_members.sort_order, EXCLUDED.sort_order),
        is_current = true, last_seen_at = now(), updated_at = now();
    END IF;

    FOR v_source IN
      SELECT source.id
      FROM public.auto_campaign_data_group_sources AS source
      WHERE source.group_id = v_group.id AND source.status IN ('baselining', 'active')
      ORDER BY source.campaign_id
    LOOP
      v_outcome := public.aka_agent_internal_route_data_group_member(
        v_source.id, v_member.id, v_batch.id, v_revision
      );
      CASE v_outcome ->> 'status'
        WHEN 'inserted' THEN v_inserted_inputs := v_inserted_inputs + 1;
        WHEN 'existing' THEN v_existing_inputs := v_existing_inputs + 1;
        WHEN 'incompatible' THEN v_incompatible := v_incompatible + 1;
        WHEN 'conflict' THEN
          v_conflict := v_conflict + 1;
          v_conflicts := v_conflicts || jsonb_build_array(jsonb_build_object(
            'rowIndex', v_row.row_index - 1,
            'code', 'canonical_alias_conflict',
            'message', 'Các định danh của dòng đang trỏ tới nhiều target khác nhau.',
            'aliases', COALESCE(v_outcome -> 'aliases', '[]'::jsonb)
          ));
        ELSE NULL;
      END CASE;
    END LOOP;
  END LOOP;

  IF v_dataset.id IS NOT NULL AND v_dataset.source = 'upload' AND v_dataset.group_id = v_group.id THEN
    SELECT count(*)::integer INTO v_removed_members
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id AND member.is_delete = false
      AND EXISTS (
        SELECT 1 FROM public.auto_account_contact_group_member_origins AS historical_origin
        WHERE historical_origin.membership_id = member.id
          AND historical_origin.dataset_id = v_dataset.id
      )
      AND NOT EXISTS (
        SELECT 1 FROM public.auto_account_contact_group_member_origins AS current_origin
        WHERE current_origin.membership_id = member.id
          AND current_origin.is_current = true
      );
    IF v_removed_members > 0 THEN
      IF NOT v_revision_started THEN
        UPDATE public.auto_account_contact_groups
        SET revision = revision + 1, updated_at = now()
        WHERE id = v_group.id
        RETURNING revision INTO v_revision;
        v_revision_started := true;
      END IF;
      UPDATE public.auto_account_contact_group_members AS member
      SET is_delete = true, change_revision = v_revision, updated_at = now()
      WHERE member.group_id = v_group.id AND member.is_delete = false
        AND EXISTS (
          SELECT 1 FROM public.auto_account_contact_group_member_origins AS historical_origin
          WHERE historical_origin.membership_id = member.id
            AND historical_origin.dataset_id = v_dataset.id
        )
        AND NOT EXISTS (
          SELECT 1 FROM public.auto_account_contact_group_member_origins AS current_origin
          WHERE current_origin.membership_id = member.id
            AND current_origin.is_current = true
        );
    END IF;

    UPDATE public.auto_account_contacts_dataset AS dataset
    SET contact_count = (
      SELECT count(*)::integer
      FROM public.auto_account_contacts_dataset_members AS member
      WHERE member.dataset_id = v_dataset.id AND member.is_current = true
    ), updated_at = now()
    WHERE dataset.id = v_dataset.id;
  END IF;
  IF NOT v_revision_started THEN v_revision := v_group.revision; END IF;

  v_result := jsonb_build_object(
    'request_id', btrim(p_request_id),
    'batch_id', v_batch.id,
    'group_id', v_group.id,
    'group_revision', v_revision,
    'inserted_membership_count', v_inserted_members,
    'reactivated_membership_count', v_reactivated_members,
    'already_member_count', v_existing_members,
    'removed_membership_count', v_removed_members,
    'inserted_input_count', v_inserted_inputs,
    'already_seen_input_count', v_existing_inputs,
    'incompatible_count', v_incompatible,
    'conflict_count', v_conflict,
    'invalid_count', v_invalid,
    'conflicts', v_conflicts
  );
  UPDATE public.auto_data_ingest_batches
  SET status = 'completed', result = v_result, updated_at = now()
  WHERE id = v_batch.id;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_finalize_data_group_campaign_v219(p_staff_id bigint, p_organization_id bigint, p_campaign_id bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_has_pending boolean;
  v_has_inflight boolean;
  v_before_hard_end boolean;
  v_hard_terminal boolean;
  v_status text;
  v_reason text;
BEGIN
  PERFORM public.aka_agent_internal_require_staff_tenant(
    p_staff_id, p_organization_id
  );
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT * INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND campaign.data_target_source_mode = 'data_group'
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_campaign_not_found'; END IF;

  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.campaign_id = v_campaign.id AND source.staff_id = p_staff_id
    AND source.organization_id = p_organization_id
  FOR UPDATE;

  SELECT EXISTS (
    SELECT 1 FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = v_campaign.id
      AND COALESCE(input_data.is_delete, false) = false
      AND input_data.status = 'chờ xử lý'
  ), EXISTS (
    SELECT 1 FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = v_campaign.id
      AND COALESCE(input_data.is_delete, false) = false
      AND input_data.status = 'đang chạy'
  ) INTO v_has_pending, v_has_inflight;

  v_before_hard_end := NOT COALESCE(v_campaign.is_delete, false)
    AND (v_campaign.schedule_end_date IS NULL OR v_campaign.schedule_end_date > now());
  v_hard_terminal := COALESCE(v_campaign.is_delete, false)
    OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now())
    OR v_campaign.status = 'hoàn thành';

  -- Hard terminal state wins over the ordinary pending-input race. No new
  -- target may start after delete/end/explicit completion; an already-running
  -- target is allowed to finish and the next finalize call completes cleanup.
  IF v_hard_terminal THEN
    IF v_source.id IS NOT NULL AND v_source.status <> 'stopped' THEN
      UPDATE public.auto_campaign_data_group_sources
      SET status = 'stopped',
          stopped_at = COALESCE(stopped_at, now()),
          stop_reason = COALESCE(stop_reason, CASE
            WHEN COALESCE(v_campaign.is_delete, false) THEN 'campaign_deleted'
            WHEN v_campaign.status = 'hoàn thành' THEN 'campaign_completed'
            ELSE 'hard_end_reached'
          END),
          updated_at = now()
      WHERE id = v_source.id;
    END IF;

    UPDATE public.auto_campaign_input_data
    SET status = 'hoàn thành',
        note = COALESCE(note, CASE
          WHEN COALESCE(v_campaign.is_delete, false) THEN 'Chiến dịch đã bị xoá'
          WHEN v_campaign.status = 'hoàn thành' THEN 'Chiến dịch đã hoàn thành'
          ELSE 'Chiến dịch đã hết hạn'
        END),
        date_action = COALESCE(date_action, now())
    WHERE campaign_id = v_campaign.id
      AND COALESCE(is_delete, false) = false
      AND status = 'chờ xử lý';
    v_has_pending := false;

    IF v_has_inflight THEN
      RETURN jsonb_build_object(
        'completed', false,
        'status', v_campaign.status,
        'reason', 'terminal_input_inflight'
      );
    END IF;

    UPDATE public.auto_campaigns
    SET status = 'hoàn thành',
        note = COALESCE(NULLIF(btrim(COALESCE(p_note, '')), ''), note),
        completed_at = COALESCE(completed_at, now()),
        updated_at = now()
    WHERE id = v_campaign.id;
    RETURN jsonb_build_object(
      'completed', true,
      'status', 'hoàn thành',
      'reason', CASE
        WHEN COALESCE(v_campaign.is_delete, false) THEN 'campaign_deleted'
        WHEN v_campaign.status = 'hoàn thành' THEN 'campaign_completed'
        ELSE 'hard_end_reached'
      END
    );
  END IF;

  -- Durable client pause wins every finalize race.
  IF v_campaign.status = 'tạm dừng' THEN
    RETURN jsonb_build_object(
      'completed', false, 'status', v_campaign.status, 'reason', 'paused'
    );
  END IF;
  IF v_has_inflight THEN
    RETURN jsonb_build_object(
      'completed', false, 'status', v_campaign.status, 'reason', 'input_inflight'
    );
  END IF;

  IF v_has_pending THEN
    v_status := 'chờ xử lý';
    v_reason := 'pending_input_raced';
    UPDATE public.auto_campaigns
    SET status = v_status,
        note = NULLIF(btrim(COALESCE(p_note, '')), ''),
        completed_at = NULL,
        updated_at = now()
    WHERE id = v_campaign.id AND status <> 'tạm dừng';
  ELSIF v_source.id IS NOT NULL AND v_source.status IN ('baselining', 'active')
    AND v_before_hard_end THEN
    v_status := 'chờ xử lý';
    v_reason := 'active_source_waiting';
    UPDATE public.auto_campaigns
    SET status = v_status,
        note = 'Chờ data mới',
        completed_at = NULL,
        updated_at = now()
    WHERE id = v_campaign.id AND status <> 'tạm dừng';
  ELSE
    v_status := 'hoàn thành';
    v_reason := CASE
      WHEN COALESCE(v_campaign.is_delete, false) THEN 'campaign_deleted'
      WHEN NOT v_before_hard_end THEN 'hard_end_reached'
      WHEN v_source.id IS NULL THEN 'source_missing'
      ELSE 'source_stopped_and_drained'
    END;
    UPDATE public.auto_campaigns
    SET status = v_status,
        note = COALESCE(NULLIF(btrim(COALESCE(p_note, '')), ''), note),
        completed_at = COALESCE(completed_at, now()),
        updated_at = now()
    WHERE id = v_campaign.id AND status <> 'tạm dừng';
  END IF;

  SELECT status INTO v_status
  FROM public.auto_campaigns
  WHERE id = v_campaign.id;
  RETURN jsonb_build_object(
    'completed', v_status = 'hoàn thành',
    'status', v_status,
    'reason', v_reason
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_mutate_contact_tags(p_staff_id bigint, p_organization_id bigint, p_contact_ids bigint[], p_tag_ids bigint[], p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE v_contact public.auto_account_contacts%ROWTYPE; v_tags bigint[];
  v_previous_batch text; v_chat_account_id bigint; v_zalo_uid text; v_conversation_type text;
  v_conversation_id bigint; v_changed integer; v_count integer:=0;
BEGIN
  IF p_mode IS NULL OR p_mode NOT IN ('add','remove') THEN RAISE EXCEPTION 'contact_tag_mode_invalid'; END IF;
  IF COALESCE(cardinality(p_contact_ids),0)>100
    THEN RAISE EXCEPTION 'contact_tag_batch_limit_exceeded'; END IF;
  SELECT COALESCE(array_agg(DISTINCT id ORDER BY id),'{}'::bigint[]) INTO v_tags
    FROM public.auto_contact_tags WHERE id=ANY(p_tag_ids) AND staff_id=p_staff_id
      AND organization_id=p_organization_id AND (p_mode='remove' OR NOT is_delete);
  IF cardinality(v_tags)=0 THEN RETURN jsonb_build_object('success',true,'count',0); END IF;
  FOR v_contact IN SELECT * FROM public.auto_account_contacts
    WHERE id=ANY(p_contact_ids) AND staff_id=p_staff_id AND organization_id=p_organization_id AND NOT is_delete
    ORDER BY id
  LOOP
    IF p_mode='add' AND EXISTS (SELECT 1 FROM public.auto_contact_tags t WHERE t.id=ANY(v_tags)
      AND t.auto_account_id IS NOT NULL AND t.auto_account_id IS DISTINCT FROM v_contact.account_id)
      THEN RAISE EXCEPTION 'contact_tag_scope_invalid'; END IF;
    SELECT conv.id,ac.chat_zalo_account_id,ac.zalo_id,ac.conversation_type
      INTO v_conversation_id,v_chat_account_id,v_zalo_uid,v_conversation_type
    FROM public.auto_account_contacts c
    JOIN public.chat_zalo_account_organization b ON b.auto_account_id=c.account_id
      AND b.organization_id=c.organization_id AND b.is_active AND c.flatform_type='zalo'
    JOIN public.chat_zalo_account_conversation ac ON ac.chat_zalo_account_id=b.chat_zalo_account_id
      AND ac.zalo_id=c.uid AND ac.conversation_type=CASE WHEN c.contact_type='person' THEN 'user' WHEN c.contact_type='group' THEN 'group' END
    JOIN public.chat_zalo_conversation conv ON conv.chat_zalo_account_organization_id=b.id
      AND conv.chat_zalo_account_conversation_id=ac.id AND conv.organization_id=c.organization_id
    WHERE c.id=v_contact.id;
    IF v_conversation_id IS NOT NULL THEN
      -- Suppress per-tag mirrors/queue writes only inside this batch. Restore
      -- before the single contact event and projection, including on errors.
      v_previous_batch:=current_setting('aka_agent.chat_tag_batch',true);
      PERFORM set_config('aka_agent.chat_tag_batch','on',true);
      BEGIN
        IF p_mode='add' THEN
          INSERT INTO public.chat_zalo_conversation_system_tag(organization_id,chat_zalo_conversation_id,auto_contact_tag_id,assigned_by_org_staff_id)
            SELECT p_organization_id,v_conversation_id,k,p_staff_id FROM unnest(v_tags) k
            ON CONFLICT(chat_zalo_conversation_id,auto_contact_tag_id) DO NOTHING;
        ELSE
          DELETE FROM public.chat_zalo_conversation_system_tag
            WHERE chat_zalo_conversation_id=v_conversation_id AND organization_id=p_organization_id AND auto_contact_tag_id=ANY(v_tags);
        END IF;
        GET DIAGNOSTICS v_changed=ROW_COUNT;
      EXCEPTION WHEN OTHERS THEN
        PERFORM set_config('aka_agent.chat_tag_batch',COALESCE(v_previous_batch,''),true);
        RAISE;
      END;
      PERFORM set_config('aka_agent.chat_tag_batch',COALESCE(v_previous_batch,''),true);
      IF v_changed>0 AND v_conversation_type='user' THEN
        PERFORM public.aka_agent_enqueue_data_group_chat_user(v_chat_account_id,v_zalo_uid,p_organization_id);
      END IF;
      PERFORM public.aka_agent_refresh_contact_chat_tags(v_contact.id);
    ELSE
      UPDATE public.auto_account_contacts SET akabiz_tag_ids=ARRAY(
        SELECT DISTINCT k FROM unnest(COALESCE(akabiz_tag_ids,'{}'::bigint[])||CASE WHEN p_mode='add' THEN v_tags ELSE '{}'::bigint[] END) k
        WHERE p_mode='add' OR NOT k=ANY(v_tags) ORDER BY k
      ),updated_at=clock_timestamp()
      WHERE id=v_contact.id AND NOT is_delete AND CASE WHEN p_mode='add'
        THEN NOT COALESCE(akabiz_tag_ids,'{}'::bigint[]) @> v_tags
        ELSE COALESCE(akabiz_tag_ids,'{}'::bigint[]) && v_tags END;
      GET DIAGNOSTICS v_changed=ROW_COUNT;
    END IF;
    IF v_changed>0 THEN v_count:=v_count+1; END IF;
  END LOOP;
  RETURN jsonb_build_object('success',true,'count',v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_normalize_facebook_identity(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw text := btrim(p_value);
  v_clean text;
  v_id text;
BEGIN
  IF v_raw = '' THEN RETURN ''; END IF;
  -- Numeric IDs are already canonical.
  IF v_raw ~ '^[0-9]+$' THEN RETURN v_raw; END IF;
  -- profile.php?id=... must be extracted before query removal.
  v_id := substring(lower(v_raw) FROM '[?&]id=([0-9]+)');
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  v_clean := regexp_replace(v_raw, '^(https?://)?((www|m|mbasic)\.)?facebook\.com/', '', 'i');
  v_clean := regexp_replace(v_clean, '[?#].*$', '');
  v_clean := regexp_replace(v_clean, '/+$', '');
  v_clean := regexp_replace(v_clean, '^(groups|people|pages)/', '', 'i');
  IF v_clean ~ '/' THEN
    -- /people/name/123 and /pages/name/123 use the final numeric component.
    v_id := substring(v_clean FROM '([0-9]+)$');
    IF v_id IS NOT NULL THEN RETURN v_id; END IF;
    v_clean := split_part(v_clean, '/', 1);
  END IF;
  RETURN lower(v_clean);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_preview_data_group_target_key(p_staff_id bigint, p_organization_id bigint, p_group_id bigint, p_membership_id bigint, p_action_id text, p_account_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_contact public.auto_account_contacts%ROWTYPE;
  v_action text := btrim(COALESCE(p_action_id, ''));
  v_platform text;
  v_contact_type text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_target_value text;
  v_identity_value text;
  v_target_kind text;
  v_scope text;
BEGIN
  IF NOT (
    -- v228: preview applies the same valid-phone-only route as materialization.
    v_action IN ('zalo_message_phone', 'zalo_add_group_member')
    AND public.aka_agent_data_group_membership_has_valid_phone(
      p_membership_id, p_group_id
    )
  ) AND NOT public.aka_agent_data_group_membership_semantic_compatible(
    p_membership_id, v_action, p_group_id
  ) THEN
    RETURN NULL;
  END IF;

  SELECT contact.*
  INTO v_contact
  FROM public.auto_account_contact_group_members AS member
  JOIN public.auto_account_contacts AS contact
    ON contact.id = member.contact_id
  WHERE member.id = p_membership_id
    AND member.group_id = p_group_id
    AND member.is_delete = false
    AND private.shared_data_member_owner(p_group_id,contact.staff_id,p_staff_id,p_organization_id)
    AND contact.organization_id = p_organization_id
    AND COALESCE(contact.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  v_platform := lower(btrim(COALESCE(v_contact.flatform_type, '')));
  v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
  v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
  v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
  v_phone := NULLIF(public.aka_agent_internal_normalize_phone(COALESCE(
    NULLIF(v_contact.phone, ''),
    NULLIF(v_contact.extra_data ->> 'phone', ''),
    CASE WHEN v_contact_type = 'phone' THEN v_contact.uid ELSE NULL END,
    ''
  )), '');
  v_email := NULLIF(lower(btrim(COALESCE(
    NULLIF(v_contact.email, ''),
    NULLIF(v_contact.extra_data ->> 'email', ''),
    CASE WHEN v_contact_type = 'email' THEN v_contact.uid ELSE NULL END,
    ''
  ))), '');
  IF v_email IS NOT NULL AND (
    v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    OR length(v_email) > 254
  ) THEN
    v_email := NULL;
  END IF;

  IF v_action IN (
    'facebook_group_post', 'facebook_join_group',
    'facebook_find_data_group'
  ) THEN
    -- v227: preview Facebook routes use semantic type plus UID/URL only.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_group';
    v_scope := 'portable';
  ELSIF v_action = 'facebook_message_uid' THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    v_scope := 'portable';
  ELSIF v_action = 'facebook_find_data_search' THEN
    v_target_value := v_uid;
    v_target_kind := 'facebook_search';
    v_scope := 'portable';
  ELSIF v_action IN (
    'facebook_comment_seeding', 'facebook_comment_seeding_post'
  ) THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := CASE
      WHEN v_action = 'facebook_comment_seeding_post' THEN 'facebook_post'
      ELSE 'facebook_comment_target'
    END;
    v_scope := 'portable';
  ELSIF v_action = 'zalo_message_phone' THEN
    IF v_phone IS NULL THEN
      RETURN NULL;
    END IF;
    v_target_value := v_phone;
    v_target_kind := 'phone';
    v_scope := 'portable';
  ELSIF v_action = 'zalo_join_group_link' THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'group' THEN
      RETURN NULL;
    END IF;
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'zalo_group_link';
    v_scope := 'portable';
  ELSIF v_action = 'email_send' THEN
    IF v_email IS NULL THEN
      RETURN NULL;
    END IF;
    v_target_value := v_email;
    v_target_kind := 'email';
    v_scope := 'portable';
  ELSIF v_action IN ('facebook_message_friend', 'facebook_group_invite') THEN
    -- v226: preview follows the portable Facebook UID/URL route.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action = 'facebook_page_post' THEN
    v_target_value := COALESCE(v_uid, v_url);
    v_target_kind := 'facebook_page';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action IN (
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer'
  ) THEN
    IF v_platform <> 'zalo'
      OR v_contact_type <> 'person'
      OR v_contact.account_id IS DISTINCT FROM p_account_id
      OR v_uid IS NULL
      OR (
        v_action = 'zalo_message_friend'
        AND v_contact.is_friend IS DISTINCT FROM true
      )
    THEN
      RETURN NULL;
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_person';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action = 'zalo_message_group' THEN
    IF v_platform <> 'zalo'
      OR v_contact_type <> 'group'
      OR v_contact.account_id IS DISTINCT FROM p_account_id
      OR v_contact.is_joined IS DISTINCT FROM true
    THEN
      RETURN NULL;
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_group';
    v_scope := 'bound:' || p_account_id::text;
  ELSIF v_action = 'zalo_add_group_member' THEN
    IF v_phone IS NOT NULL THEN
      v_target_value := v_phone;
      v_target_kind := 'phone';
      v_scope := 'portable';
    ELSIF v_platform = 'zalo'
      AND v_contact_type = 'person'
      AND v_uid IS NOT NULL
      AND v_contact.account_id IS NOT DISTINCT FROM p_account_id
    THEN
      v_target_value := v_uid;
      v_target_kind := 'zalo_person';
      v_scope := 'bound:' || p_account_id::text;
    ELSE
      RETURN NULL;
    END IF;
  ELSE
    RETURN NULL;
  END IF;

  IF NULLIF(v_target_value, '') IS NULL THEN
    RETURN NULL;
  END IF;

  IF v_target_kind LIKE 'facebook_%' THEN
    v_identity_value := COALESCE(
      NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_uid), ''),
      NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_url), ''),
      NULLIF(
        public.aka_agent_internal_normalize_facebook_identity(v_target_value),
        ''
      )
    );
  ELSIF v_target_kind = 'email' THEN
    v_identity_value := lower(v_target_value);
  ELSE
    v_identity_value := v_target_value;
  END IF;
  IF NULLIF(v_identity_value, '') IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN v_scope || ':' || v_target_kind || ':' || v_identity_value;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_require_zalo_server_data_group_runtime(p_staff_id bigint, p_organization_id bigint, p_expected_mode_revision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_staff_organization_id bigint;
  v_capabilities record;
  v_expected_mode_revision text := btrim(COALESCE(p_expected_mode_revision, ''));
BEGIN
  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR v_expected_mode_revision = ''
  THEN
    RAISE EXCEPTION 'data_group_server_runtime_not_owner';
  END IF;

  SELECT staff.organization_id INTO v_staff_organization_id
  FROM public.org_staff AS staff
  WHERE staff.id = p_staff_id
    AND staff.organization_id = p_organization_id
    AND staff.is_active = true
  FOR SHARE OF staff;

  IF NOT FOUND OR v_staff_organization_id IS DISTINCT FROM p_organization_id THEN
    RAISE EXCEPTION 'data_group_server_runtime_not_owner';
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT * INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(p_organization_id);

  IF NOT COALESCE(v_capabilities.qr_enabled, false)
    OR NOT COALESCE(v_capabilities.server_enabled, false)
    OR btrim(COALESCE(v_capabilities.capability_revision, ''))
      IS DISTINCT FROM v_expected_mode_revision
  THEN
    RAISE EXCEPTION 'data_group_server_runtime_not_owner';
  END IF;
END;
$function$

