CREATE OR REPLACE FUNCTION public.aka_agent_internal_route_data_group_member(p_source_id bigint, p_membership_id bigint, p_batch_id bigint, p_group_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_campaign_id bigint;
  v_action_id text;
  v_group_id bigint;
  v_staff_id bigint;
  v_organization_id bigint;
  v_campaign_is_delete boolean;
  v_campaign_schedule_end_date timestamptz;
BEGIN
  -- V409: serialize against sharing edits before joining the existing campaign barrier.
  SELECT group_id,staff_id,organization_id INTO v_group_id,v_staff_id,v_organization_id
    FROM public.auto_campaign_data_group_sources WHERE id=p_source_id;
  IF v_group_id IS NOT NULL AND NOT private.lock_read_data_group(v_group_id,v_staff_id,v_organization_id) THEN
    SELECT campaign_id INTO v_campaign_id FROM public.auto_campaign_data_group_sources WHERE id=p_source_id;
    PERFORM public.aka_agent_lock_campaign_input_serialization(v_campaign_id);
    UPDATE public.auto_campaign_data_group_sources SET status='stopped',stop_reason='sharing_revoked',stopped_at=now(),updated_at=now()
      WHERE id=p_source_id AND status IN ('active','baselining');
    RETURN jsonb_build_object('status','no_intake','reason','sharing_revoked');
  END IF;
  SELECT
    campaign.id,
    campaign.action_id,
    source.group_id,
    campaign.staff_id,
    campaign.organization_id
  INTO
    v_campaign_id,
    v_action_id,
    v_group_id,
    v_staff_id,
    v_organization_id
  FROM public.auto_campaign_data_group_sources AS source
  JOIN public.auto_campaigns AS campaign
    ON campaign.id = source.campaign_id
  WHERE source.id = p_source_id;

  IF v_campaign_id IS NOT NULL
    AND EXISTS (
      SELECT 1
      FROM public.auto_account_contact_group_members AS member
      WHERE member.id = p_membership_id
        AND member.group_id = v_group_id
    )
    AND NOT (
      -- v228: valid-phone routes ignore semantic/platform/contact/account and
      -- relationship metadata. UID-only add-member routing does not enter here.
      v_action_id IN ('zalo_message_phone', 'zalo_add_group_member')
      AND public.aka_agent_data_group_membership_has_valid_phone(
        p_membership_id, v_group_id
      )
    )
    AND NOT public.aka_agent_data_group_membership_semantic_compatible(
      p_membership_id, v_action_id, v_group_id
    )
  THEN
    RETURN jsonb_build_object(
      'status', 'incompatible',
      'reason', 'data_group_member_semantic_type_mismatch'
    );
  END IF;

  IF v_campaign_id IS NOT NULL THEN
    PERFORM public.aka_agent_lock_campaign_input_serialization(v_campaign_id);

    SELECT
      COALESCE(campaign.is_delete, false),
      campaign.schedule_end_date
    INTO
      v_campaign_is_delete,
      v_campaign_schedule_end_date
    FROM public.auto_campaigns AS campaign
    WHERE campaign.id = v_campaign_id
      AND campaign.staff_id = v_staff_id
      AND campaign.organization_id = v_organization_id
      AND campaign.data_target_source_mode = 'data_group'
    FOR UPDATE OF campaign;

    IF FOUND AND (
      v_campaign_is_delete
      OR (
        v_campaign_schedule_end_date IS NOT NULL
        AND v_campaign_schedule_end_date <= now()
      )
    ) THEN
      PERFORM public.aka_agent_internal_finalize_data_group_campaign_v219(
        v_staff_id,
        v_organization_id,
        v_campaign_id,
        CASE
          WHEN v_campaign_is_delete THEN 'Chiến dịch đã bị xoá'
          ELSE 'Chiến dịch đã hết hạn'
        END
      );
      RETURN jsonb_build_object(
        'status', 'no_intake', 'reason', 'campaign_hard_ended'
      );
    END IF;
  END IF;

  RETURN public.aka_agent_internal_route_data_group_member_v205_internal(
    p_source_id, p_membership_id, p_batch_id, p_group_revision
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_route_data_group_member_v186_internal(p_source_id bigint, p_membership_id bigint, p_batch_id bigint, p_group_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source public.auto_campaign_data_group_sources%ROWTYPE;
  v_campaign public.auto_campaigns%ROWTYPE;
  v_member public.auto_account_contact_group_members%ROWTYPE;
  v_contact public.auto_account_contacts%ROWTYPE;
  v_account public.auto_accounts%ROWTYPE;
  v_action text;
  v_platform text;
  v_contact_type text;
  v_name text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_input_uid text;
  v_input_phone text;
  v_input_email text;
  v_target_value text;
  v_identity_value text;
  v_uid_identity text;
  v_url_identity text;
  v_allow_alias_resolution boolean := false;
  v_target_kind text;
  v_scope text;
  v_candidate_key text;
  v_canonical_key text;
  v_aliases text[] := '{}'::text[];
  v_mapped_keys text[] := '{}'::text[];
  v_payload jsonb;
  v_input_id bigint;
  v_inserted boolean := false;
  v_info1 text;
  v_info2 text;
  v_info3 text;
  v_info4 text;
  v_info5 text;
  v_phone_carrier text;
BEGIN
  SELECT * INTO v_source
  FROM public.auto_campaign_data_group_sources AS source
  WHERE source.id = p_source_id;
  IF NOT FOUND OR v_source.status NOT IN ('baselining', 'active') THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'source_stopped');
  END IF;

  SELECT * INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = v_source.campaign_id
  FOR UPDATE;
  IF FOUND AND v_campaign.data_target_source_mode = 'data_group'
    AND (
      COALESCE(v_campaign.is_delete, false)
      OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now())
    )
  THEN
    EXECUTE 'SELECT public.aka_agent_finalize_data_group_campaign($1, $2, $3, $4)'
    USING v_source.staff_id, v_source.organization_id, v_campaign.id,
      CASE WHEN COALESCE(v_campaign.is_delete, false)
        THEN 'Chiến dịch đã bị xoá' ELSE 'Chiến dịch đã hết hạn' END;
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'campaign_hard_ended');
  END IF;
  IF NOT FOUND
    OR v_campaign.staff_id IS DISTINCT FROM v_source.staff_id
    OR v_campaign.organization_id IS DISTINCT FROM v_source.organization_id
    OR COALESCE(v_campaign.is_delete, false)
    OR v_campaign.data_target_source_mode <> 'data_group'
    OR v_campaign.data_group_id IS DISTINCT FROM v_source.group_id
    OR v_campaign.status NOT IN ('chờ xử lý', 'tạm dừng', 'đang chạy')
    OR (v_campaign.schedule_end_date IS NOT NULL AND v_campaign.schedule_end_date <= now())
  THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'campaign_terminal');
  END IF;

  SELECT * INTO v_member
  FROM public.auto_account_contact_group_members AS member
  WHERE member.id = p_membership_id
    AND member.group_id = v_source.group_id
    AND member.is_delete = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'membership_inactive');
  END IF;

  SELECT * INTO v_contact
  FROM public.auto_account_contacts AS contact
  WHERE contact.id = v_member.contact_id
    AND private.shared_data_member_owner(v_source.group_id,contact.staff_id,v_source.staff_id,v_source.organization_id)
    AND contact.organization_id = v_source.organization_id
    AND COALESCE(contact.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'contact_inactive');
  END IF;

  SELECT * INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = v_campaign.account_id
    AND account.staff_id = v_source.staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_source.organization_id)
    AND COALESCE(account.is_delete, false) = false;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'no_intake', 'reason', 'campaign_account_inactive');
  END IF;

  v_action := btrim(COALESCE(v_campaign.action_id, ''));
  v_platform := lower(btrim(COALESCE(v_contact.flatform_type, '')));
  v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
  v_name := NULLIF(btrim(COALESCE(v_contact.name, '')), '');
  v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
  v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
  v_phone := public.aka_agent_internal_normalize_phone(COALESCE(
    NULLIF(v_contact.phone, ''), NULLIF(v_contact.extra_data ->> 'phone', ''),
    CASE WHEN v_contact_type = 'phone' THEN v_contact.uid ELSE NULL END, ''
  ));
  v_phone := NULLIF(v_phone, '');
  v_email := NULLIF(lower(btrim(COALESCE(
    NULLIF(v_contact.email, ''), NULLIF(v_contact.extra_data ->> 'email', ''),
    CASE WHEN v_contact_type = 'email' THEN v_contact.uid ELSE NULL END, ''
  ))), '');
  IF v_email IS NOT NULL AND (v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
      OR length(v_email) > 254) THEN
    v_email := NULL;
  END IF;
  v_info1 := NULLIF(v_contact.extra_data ->> 'info1', '');
  v_info2 := NULLIF(v_contact.extra_data ->> 'info2', '');
  v_info3 := NULLIF(v_contact.extra_data ->> 'info3', '');
  v_info4 := NULLIF(v_contact.extra_data ->> 'info4', '');
  v_info5 := NULLIF(v_contact.extra_data ->> 'info5', '');
  v_phone_carrier := COALESCE(
    NULLIF(v_contact.extra_data ->> 'phoneCarrier', ''),
    NULLIF(v_contact.extra_data ->> 'phone_carrier', '')
  );

  -- Portable Facebook routes.
  IF v_action IN ('facebook_group_post', 'facebook_join_group', 'facebook_find_data_group') THEN
    -- v227: Facebook routes use semantic type plus UID/URL only.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_group';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'facebook_message_uid' THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'facebook_find_data_search' THEN
    v_target_value := v_uid;
    v_target_kind := 'facebook_search';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action IN ('facebook_comment_seeding', 'facebook_comment_seeding_post') THEN
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := CASE WHEN v_action = 'facebook_comment_seeding_post'
      THEN 'facebook_post' ELSE 'facebook_comment_target' END;
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'zalo_message_phone' THEN
    IF v_phone IS NULL THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'valid_phone_required');
    END IF;
    v_target_value := v_phone;
    v_target_kind := 'phone';
    v_scope := 'portable';
    v_input_phone := v_target_value;
  ELSIF v_action = 'zalo_join_group_link' THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'group' THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'zalo_group_required');
    END IF;
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'zalo_group_link';
    v_scope := 'portable';
    v_input_uid := v_target_value;
  ELSIF v_action = 'email_send' THEN
    IF v_email IS NULL THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'valid_email_required');
    END IF;
    v_target_value := v_email;
    v_target_kind := 'email';
    v_scope := 'portable';
    v_input_email := v_target_value;

  -- Account-bound routes.
  ELSIF v_action IN ('facebook_message_friend', 'facebook_group_invite') THEN
    -- v226: Facebook UID/URL targets are portable across source accounts.
    -- is_friend and contact.account_id are scan metadata only.
    v_target_value := COALESCE(v_url, v_uid);
    v_target_kind := 'facebook_person';
    -- Retain the legacy per-campaign key namespace so existing active inputs
    -- are not duplicated when this migration is applied mid-campaign.
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;
  ELSIF v_action = 'facebook_page_post' THEN
    -- v226: Page ID/URL validity is sufficient; source account is not binding.
    v_target_value := COALESCE(v_uid, v_url);
    v_target_kind := 'facebook_page';
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;
  ELSIF v_action IN (
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer'
  ) THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'person'
      OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'bound_zalo_person_required');
    END IF;
    IF v_action = 'zalo_message_friend' AND v_contact.is_friend IS DISTINCT FROM true THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'bound_zalo_friend_required');
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_person';
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;
  ELSIF v_action = 'zalo_message_group' THEN
    IF v_platform <> 'zalo' OR v_contact_type <> 'group'
      OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id
      OR v_contact.is_joined IS DISTINCT FROM true THEN
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'bound_joined_zalo_group_required');
    END IF;
    v_target_value := v_uid;
    v_target_kind := 'zalo_group';
    v_scope := 'bound:' || v_campaign.account_id::text;
    v_input_uid := v_target_value;

  -- Hybrid: a valid phone is portable and must force uid=''; UID-only remains
  -- account-bound so one account's Zalo identity is never used by another.
  ELSIF v_action = 'zalo_add_group_member' THEN
    IF v_phone IS NOT NULL THEN
      v_target_value := v_phone;
      v_target_kind := 'phone';
      v_scope := 'portable';
      v_input_phone := v_phone;
      v_input_uid := '';
    ELSIF v_platform = 'zalo' AND v_contact_type = 'person'
      AND v_uid IS NOT NULL
      AND v_contact.account_id IS NOT DISTINCT FROM v_campaign.account_id THEN
      v_target_value := v_uid;
      v_target_kind := 'zalo_person';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_uid;
    ELSE
      RETURN jsonb_build_object('status', 'incompatible', 'reason', 'hybrid_target_not_routable');
    END IF;
  ELSE
    -- Includes SMS, voice, Zalo realtime, cancel-request and every future action
    -- until its delivery contract is explicitly added here.
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'unsupported_action');
  END IF;

  IF NULLIF(v_target_value, '') IS NULL THEN
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'target_value_missing');
  END IF;

  -- Canonicalization is action-aware.  Phone/email routes intentionally carry
  -- no unrelated UID/URL aliases; doing so could merge two different people
  -- merely because an imported row happened to contain extra columns.
  IF v_target_kind LIKE 'facebook_%' THEN
    v_uid_identity := CASE WHEN v_uid IS NULL THEN NULL
      ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_uid), '') END;
    v_url_identity := CASE WHEN v_url IS NULL THEN NULL
      ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_url), '') END;
    v_identity_value := COALESCE(
      v_uid_identity,
      v_url_identity,
      NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_target_value), '')
    );
    -- UID and URL stored on the same Facebook contact are explicit aliases for
    -- that row. Canonical identity prefers UID while input.uid keeps the raw
    -- URL/value required by the runtime.
    v_allow_alias_resolution := true;
  ELSIF v_target_kind = 'email' THEN
    v_identity_value := lower(v_target_value);
  ELSE
    v_identity_value := v_target_value;
  END IF;
  IF NULLIF(v_identity_value, '') IS NULL THEN
    RETURN jsonb_build_object('status', 'incompatible', 'reason', 'canonical_identity_missing');
  END IF;
  v_candidate_key := v_scope || ':' || v_target_kind || ':' || v_identity_value;
  v_aliases := array_append(v_aliases, v_candidate_key);
  IF v_target_kind LIKE 'facebook_%' AND v_uid_identity IS NOT NULL THEN
    v_aliases := array_append(
      v_aliases, v_scope || ':' || v_target_kind || ':' || v_uid_identity
    );
  END IF;
  IF v_target_kind LIKE 'facebook_%' AND v_url_identity IS NOT NULL THEN
    v_aliases := array_append(
      v_aliases, v_scope || ':' || v_target_kind || ':' || v_url_identity
    );
  END IF;
  SELECT COALESCE(array_agg(DISTINCT alias.canonical_target_key), '{}'::text[])
  INTO v_mapped_keys
  FROM public.auto_campaign_input_target_aliases AS alias
  WHERE alias.campaign_id = v_campaign.id AND alias.alias_key = ANY(v_aliases);

  IF cardinality(v_mapped_keys) > 1
    OR (
      cardinality(v_mapped_keys) = 1
      AND NOT v_allow_alias_resolution
      AND v_mapped_keys[1] IS DISTINCT FROM v_candidate_key
    )
  THEN
    UPDATE public.auto_campaign_input_target_aliases AS alias
    SET conflict_count = alias.conflict_count + 1,
        last_conflict_at = now(),
        last_conflict_payload = jsonb_build_object(
          'membershipId', v_member.id,
          'candidateCanonicalKey', v_candidate_key,
          'mappedCanonicalKeys', to_jsonb(v_mapped_keys),
          'aliases', to_jsonb(v_aliases)
        ),
        updated_at = now()
    WHERE alias.campaign_id = v_campaign.id AND alias.alias_key = ANY(v_aliases);
    RETURN jsonb_build_object(
      'status', 'conflict', 'reason', 'canonical_alias_conflict',
      'aliases', to_jsonb(v_aliases), 'canonicalKeys', to_jsonb(v_mapped_keys)
    );
  END IF;
  -- One established Facebook alias may resolve a UID-only or URL-only row.
  -- All other actions require exact candidate agreement.
  v_canonical_key := CASE
    WHEN v_allow_alias_resolution AND cardinality(v_mapped_keys) = 1
      THEN v_mapped_keys[1]
    ELSE v_candidate_key
  END;

  v_payload := jsonb_strip_nulls(jsonb_build_object(
    'name', COALESCE(v_name, v_target_value),
    'phone', v_input_phone,
    'phone_carrier', v_phone_carrier,
    'uid', v_input_uid,
    'email', v_input_email,
    'info1', v_info1, 'info2', v_info2, 'info3', v_info3,
    'info4', v_info4, 'info5', v_info5,
    'contact_id', v_contact.id,
    'membership_id', v_member.id,
    'source_account_id', v_contact.account_id,
    'contact_type', v_contact.contact_type,
    'flatform_type', v_contact.flatform_type,
    'canonical_target_key', v_canonical_key
  ));

  INSERT INTO public.auto_campaign_input_data (
    campaign_id, input_id, name, phone, phone_carrier, uid, email,
    info1, info2, info3, info4, info5, status, schedule, is_delete,
    canonical_target_key, created_at
  ) VALUES (
    v_campaign.id, NULL, COALESCE(v_name, v_target_value),
    v_input_phone, v_phone_carrier, v_input_uid, v_input_email,
    v_info1, v_info2, v_info3, v_info4, v_info5,
    'chờ xử lý', COALESCE(v_campaign.schedule, now()), false,
    v_canonical_key, now()
  )
  ON CONFLICT (campaign_id, canonical_target_key)
    WHERE canonical_target_key IS NOT NULL AND COALESCE(is_delete, false) = false
  DO NOTHING
  RETURNING id INTO v_input_id;

  IF v_input_id IS NULL THEN
    SELECT input_data.id INTO v_input_id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = v_campaign.id
      AND input_data.canonical_target_key = v_canonical_key
      AND COALESCE(input_data.is_delete, false) = false
    FOR UPDATE;
  ELSE
    v_inserted := true;
  END IF;

  INSERT INTO public.auto_campaign_input_target_aliases (
    campaign_id, alias_key, canonical_target_key, input_data_id
  )
  SELECT v_campaign.id, candidate.alias_key, v_canonical_key, v_input_id
  FROM (SELECT DISTINCT unnest(v_aliases) AS alias_key) AS candidate
  ON CONFLICT (campaign_id, alias_key) DO UPDATE
  SET input_data_id = EXCLUDED.input_data_id,
      updated_at = now()
  WHERE auto_campaign_input_target_aliases.canonical_target_key = EXCLUDED.canonical_target_key;

  INSERT INTO public.auto_campaign_input_origins (
    input_data_id, source_id, group_id, membership_id, batch_id,
    group_revision, canonical_target_key, payload_snapshot
  ) VALUES (
    v_input_id, v_source.id, v_source.group_id, v_member.id, p_batch_id,
    p_group_revision, v_canonical_key, v_payload
  ) ON CONFLICT DO NOTHING;

  UPDATE public.auto_campaign_data_group_sources
  SET last_ingest_at = now(), updated_at = now()
  WHERE id = v_source.id;

  UPDATE public.auto_campaigns
  SET note = NULL, updated_at = now()
  WHERE id = v_campaign.id
    AND note IN ('Chờ data phù hợp', 'Chờ data mới');

  RETURN jsonb_build_object(
    'status', CASE WHEN v_inserted THEN 'inserted' ELSE 'existing' END,
    'inputDataId', v_input_id,
    'canonicalTargetKey', v_canonical_key
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_route_group_snapshot(p_source_id bigint, p_batch_id bigint, p_group_revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_member_id bigint;
  v_outcome jsonb;
  v_inserted integer := 0;
  v_existing integer := 0;
  v_incompatible integer := 0;
  v_conflict integer := 0;
BEGIN
  FOR v_member_id IN
    SELECT member.id
    FROM public.auto_campaign_data_group_sources AS source
    JOIN public.auto_account_contact_group_members AS member ON member.group_id = source.group_id
    WHERE source.id = p_source_id AND member.is_delete = false
    ORDER BY member.id
  LOOP
    v_outcome := public.aka_agent_internal_route_data_group_member(
      p_source_id, v_member_id, p_batch_id, p_group_revision
    );
    CASE v_outcome ->> 'status'
      WHEN 'inserted' THEN v_inserted := v_inserted + 1;
      WHEN 'existing' THEN v_existing := v_existing + 1;
      WHEN 'incompatible' THEN v_incompatible := v_incompatible + 1;
      WHEN 'conflict' THEN v_conflict := v_conflict + 1;
      ELSE NULL;
    END CASE;
  END LOOP;
  RETURN jsonb_build_object(
    'inserted_input_count', v_inserted,
    'already_seen_input_count', v_existing,
    'incompatible_count', v_incompatible,
    'conflict_count', v_conflict
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_validate_send_exclusion_rules(p_rules jsonb, p_staff bigint, p_org bigint, p_account bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r jsonb; f public.auto_filter_fields%ROWTYPE; m public.auto_filter_field_operators%ROWTYPE; vals jsonb; v jsonb; opts jsonb;
BEGIN
 IF jsonb_typeof(p_rules) IS DISTINCT FROM 'array' OR jsonb_array_length(p_rules)=0 OR jsonb_array_length(p_rules)>100
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_rules) x WHERE x->>'isEnabled'='true') THEN RAISE EXCEPTION 'send_exclusion_rules_required'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rules) x GROUP BY x->>'fieldId' HAVING count(*)>1) THEN RAISE EXCEPTION 'send_exclusion_duplicate_field'; END IF;
 opts:=public.aka_agent_internal_send_exclusion_options(p_staff,p_org,p_account);
 FOR r IN SELECT * FROM jsonb_array_elements(p_rules) LOOP
  SELECT * INTO f FROM public.auto_filter_fields WHERE id=(r->>'fieldId')::bigint AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'send_exclusion_field_unavailable'; END IF;
  SELECT m0.* INTO m FROM public.auto_filter_field_operators m0 JOIN public.auto_filter_operators o ON o.id=m0.operator_id AND o.is_active
   WHERE m0.field_id=f.id AND m0.operator_id=(r->>'operatorId')::bigint;
  IF NOT FOUND THEN RAISE EXCEPTION 'send_exclusion_operator_unavailable'; END IF;
  IF NOT COALESCE((r->>'isEnabled')::boolean,false) THEN CONTINUE; END IF;
  vals:=CASE WHEN jsonb_typeof(r->'value')='array' THEN r->'value' WHEN r->'value' IS NOT NULL AND r->'value'<>'null' THEN jsonb_build_array(r->'value') ELSE '[]' END;
  IF jsonb_array_length(vals)<m.min_values OR jsonb_array_length(vals)>m.max_values THEN RAISE EXCEPTION 'send_exclusion_value_count'; END IF;
  FOR v IN SELECT * FROM jsonb_array_elements(vals) LOOP
   IF m.value_type='number' THEN
    IF jsonb_typeof(v)<>'number' THEN RAISE EXCEPTION 'send_exclusion_number_required'; END IF;
    IF (m.validation_config ? 'min' AND (v#>>'{}')::numeric<(m.validation_config->>'min')::numeric)
    OR (m.validation_config ? 'max' AND (v#>>'{}')::numeric>(m.validation_config->>'max')::numeric)
    OR (COALESCE((m.validation_config->>'integer')::boolean,false) AND trunc((v#>>'{}')::numeric)<>(v#>>'{}')::numeric) THEN RAISE EXCEPTION 'send_exclusion_number_range'; END IF;
   ELSIF m.value_type='date' THEN
    IF jsonb_typeof(v)<>'string' OR (v#>>'{}') !~ '^\d{4}-\d{2}-\d{2}$' THEN RAISE EXCEPTION 'send_exclusion_date_required'; END IF;
    PERFORM (v#>>'{}')::date;
   ELSIF m.value_type='text' AND (jsonb_typeof(v)<>'string' OR length(btrim(v#>>'{}'))=0) THEN RAISE EXCEPTION 'send_exclusion_text_required';
   ELSIF m.value_type='boolean' AND jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'send_exclusion_boolean_required'; END IF;
   IF f.options_source<>'none' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(opts) o WHERE (o->>'fieldId')::bigint=f.id AND o->'value'=v) THEN RAISE EXCEPTION 'send_exclusion_option_unavailable'; END IF;
  END LOOP;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_internal_validate_send_exclusion_selection(p_map jsonb, p_staff bigint, p_org bigint, p_account bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE entry record; aid bigint; gid bigint; ids bigint[]; group_data jsonb;
BEGIN
 IF p_map IS NULL THEN RETURN; END IF;
 IF jsonb_typeof(p_map)<>'object' OR NOT p_map ? p_account::text THEN RAISE EXCEPTION 'send_exclusion_account_configuration_missing'; END IF;
 FOR entry IN SELECT * FROM jsonb_each(p_map) LOOP
  IF jsonb_typeof(entry.value) IS DISTINCT FROM 'object' OR NOT entry.value ? 'groupId'
    OR (entry.value->'groupId'<>'null' AND jsonb_typeof(entry.value->'groupId')<>'number') THEN RAISE EXCEPTION 'send_exclusion_group_reference_invalid'; END IF;
  aid:=entry.key::bigint;
  IF NOT EXISTS(SELECT 1 FROM public.auto_accounts WHERE id=aid AND staff_id=p_staff AND organization_id=p_org AND flatform_type='zalo' AND NOT is_delete) THEN RAISE EXCEPTION 'send_exclusion_account_not_found'; END IF;
  gid:=(entry.value->>'groupId')::bigint;
  IF gid IS NOT NULL THEN
   SELECT public.aka_agent_internal_send_exclusion_group(g.id) INTO group_data FROM public.auto_campaign_send_exclusion_groups g
    WHERE g.id=gid AND g.staff_id=p_staff AND g.organization_id=p_org AND g.account_id=aid AND NOT g.is_delete;
   IF group_data IS NULL THEN RAISE EXCEPTION 'send_exclusion_group_not_found'; END IF;
   PERFORM public.aka_agent_internal_validate_send_exclusion_rules(group_data->'rules',p_staff,p_org,aid);
  END IF;
  IF jsonb_typeof(entry.value->'blocklistIds') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'send_exclusion_blocklists_invalid'; END IF;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(entry.value->'blocklistIds') v WHERE jsonb_typeof(v)<>'number' OR (v#>>'{}')::numeric<=0 OR trunc((v#>>'{}')::numeric)<>(v#>>'{}')::numeric) THEN RAISE EXCEPTION 'send_exclusion_blocklists_invalid'; END IF;
  SELECT ARRAY(SELECT DISTINCT value::bigint FROM jsonb_array_elements_text(entry.value->'blocklistIds')) INTO ids;
  IF cardinality(ids)<>(SELECT count(*) FROM public.auto_account_contact_groups g WHERE g.id=ANY(ids) AND g.account_id=aid AND g.staff_id=p_staff AND g.organization_id=p_org AND NOT g.is_delete AND g.purpose='zalo_friend_blocklist' AND g.contact_type='person') THEN RAISE EXCEPTION 'send_exclusion_blocklist_not_found'; END IF;
 END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_lock_campaign_input_serialization(p_campaign_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF p_campaign_id IS NULL OR p_campaign_id <= 0 THEN
    RAISE EXCEPTION 'campaign_input_serialization_id_invalid';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'aka-agent-campaign-input-serialization:' || p_campaign_id::text, 0
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_prepare_device_change(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username);
  IF NOT FOUND THEN RETURN jsonb_build_object('code', 'not_found'); END IF;
  IF NOT s.is_active THEN RETURN jsonb_build_object('code', 'inactive'); END IF;
  RETURN jsonb_build_object('code', 'prepared', 'binding', jsonb_build_object(
    'staffId', s.id::text, 'hash', s.device_fingerprint_hash, 'boundAt', s.device_bound_at));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_prepare_device_change_v2(p_username text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s public.org_staff%ROWTYPE; revision text;
BEGIN
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('code', 'not_found'); END IF;
  IF NOT s.is_active THEN RETURN jsonb_build_object('code', 'inactive'); END IF;
  SELECT xmin::text INTO revision FROM public.org_staff WHERE id=s.id;
  RETURN jsonb_build_object('code', 'prepared', 'binding', jsonb_build_object(
    'staffId', s.id::text, 'hash', s.aka_agent_device_fingerprint_hash, 'revision', revision, 'version', 2));
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_refresh_contact_chat_tags(p_contact_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_tags bigint[]; v_previous text;
BEGIN
  IF current_setting('aka_agent.chat_tag_writeback',true)='on' THEN RETURN; END IF;
  -- Read canonical tags only after owning the row, so a waiting mirror cannot
  -- overwrite tags committed while it was waiting.
  PERFORM 1 FROM public.auto_account_contacts WHERE id=p_contact_id AND NOT is_delete FOR UPDATE;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT ARRAY(
    SELECT t.id FROM public.chat_zalo_conversation_system_tag link
    JOIN public.auto_contact_tags t ON t.id=link.auto_contact_tag_id
    WHERE link.chat_zalo_conversation_id=conv.id AND link.organization_id=c.organization_id
      AND t.staff_id=c.staff_id AND t.organization_id=c.organization_id AND NOT t.is_delete
      AND (t.auto_account_id IS NULL OR t.auto_account_id=c.account_id)
    ORDER BY t.id
  ) INTO v_tags
  FROM public.auto_account_contacts c
    JOIN public.chat_zalo_account_organization b ON b.auto_account_id=c.account_id
      AND b.organization_id=c.organization_id AND b.is_active AND c.flatform_type='zalo'
    JOIN public.chat_zalo_account_conversation ac ON ac.chat_zalo_account_id=b.chat_zalo_account_id
      AND ac.zalo_id=c.uid AND ac.conversation_type=CASE WHEN c.contact_type='person' THEN 'user' WHEN c.contact_type='group' THEN 'group' END
    JOIN public.chat_zalo_conversation conv ON conv.chat_zalo_account_organization_id=b.id
      AND conv.chat_zalo_account_conversation_id=ac.id AND conv.organization_id=c.organization_id
  WHERE c.id=p_contact_id;
  IF NOT FOUND THEN RETURN; END IF;
  v_previous:=current_setting('aka_agent.chat_tag_projection',true);
  PERFORM set_config('aka_agent.chat_tag_projection','on',true);
  BEGIN
    UPDATE public.auto_account_contacts SET akabiz_tag_ids=v_tags,updated_at=clock_timestamp()
      WHERE id=p_contact_id AND NOT is_delete AND akabiz_tag_ids IS DISTINCT FROM v_tags;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('aka_agent.chat_tag_projection',COALESCE(v_previous,''),true);
    RAISE;
  END;
  PERFORM set_config('aka_agent.chat_tag_projection',COALESCE(v_previous,''),true);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reset_device_binding(p_username text, p_password text, p_source text, p_request_id uuid, p_expected_binding jsonb, p_device jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  s public.org_staff%ROWTYPE;
  h public.auto_staff_device_change_history%ROWTYPE;
  remaining integer;
  remaining_after integer;
  outcome text;
  stamp timestamptz;
  device jsonb;
BEGIN
  IF p_source IS NULL OR p_source NOT IN ('login', 'account_menu') OR p_request_id IS NULL
     OR jsonb_typeof(p_expected_binding) IS DISTINCT FROM 'object'
     OR NOT (p_expected_binding ?& ARRAY['staffId','hash','boundAt'])
     OR jsonb_typeof(p_device) IS DISTINCT FROM 'object'
     OR coalesce(p_device->>'fingerprintHash','') !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid device change request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'changed',false,'code','not_found','remainingChanges',null); END IF;
  remaining := coalesce(s.device_changes_remaining, 5);
  IF NOT s.is_active THEN outcome := 'inactive';
  ELSIF p_source = 'account_menu' AND s.password IS DISTINCT FROM p_password THEN outcome := 'not_authorized';
  ELSIF s.id::text IS DISTINCT FROM p_expected_binding->>'staffId' THEN outcome := 'binding_conflict';
  END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',false,'changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Whitelist metadata: the history must never persist arbitrary credentials.
  device := jsonb_build_object('fingerprintHash',p_device->>'fingerprintHash',
    'label',left(p_device->>'label',255),'platform',left(p_device->>'platform',20),
    'appVersion',left(p_device->>'appVersion',50));
  SELECT * INTO h FROM public.auto_staff_device_change_history WHERE request_id = p_request_id;
  IF FOUND THEN
    IF h.staff_id <> s.id OR h.source <> p_source
       OR h.requesting_device->>'fingerprintHash' IS DISTINCT FROM device->>'fingerprintHash'
       OR h.old_binding->>'hash' IS DISTINCT FROM p_expected_binding->>'hash'
       OR (h.old_binding->>'boundAt')::timestamptz IS DISTINCT FROM (p_expected_binding->>'boundAt')::timestamptz THEN
      RETURN jsonb_build_object('success',false,'changed',false,'code','binding_conflict','remainingChanges',remaining);
    END IF;
    RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',h.remaining_after);
  END IF;

  IF s.device_fingerprint_hash IS NULL THEN outcome := 'already_unbound';
  ELSIF p_source = 'account_menu' AND s.device_fingerprint_hash IS DISTINCT FROM device->>'fingerprintHash' THEN outcome := 'not_authorized';
  ELSIF s.device_fingerprint_hash IS DISTINCT FROM p_expected_binding->>'hash'
     OR s.device_bound_at IS DISTINCT FROM (p_expected_binding->>'boundAt')::timestamptz THEN outcome := 'binding_conflict';
  ELSIF p_source = 'login' AND remaining <= 0 THEN outcome := 'quota_exhausted';
  END IF;
  stamp := clock_timestamp();
  IF outcome IS NULL AND p_source = 'login' AND EXISTS (
    SELECT 1 FROM public.auto_staff_device_presence
    WHERE staff_id = s.id AND ended_at IS NULL AND last_seen_at > stamp - interval '120 seconds'
  ) THEN outcome := 'device_online'; END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',outcome = 'already_unbound','changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Only the unauthenticated login flow consumes the device-change quota.
  remaining_after := remaining - CASE WHEN p_source = 'login' THEN 1 ELSE 0 END;
  UPDATE public.org_staff SET device_fingerprint_hash = NULL, device_label = NULL,
    device_platform = NULL, device_bound_at = NULL, device_last_seen_at = NULL,
    device_changes_remaining = CASE WHEN p_source = 'login' THEN remaining_after ELSE s.device_changes_remaining END,
    updated_at = stamp
  WHERE id = s.id;
  UPDATE public.auto_staff_device_login_settings SET remember_login = false, auto_login = false, updated_at = stamp
  WHERE staff_id = s.id AND device_fingerprint_hash = s.device_fingerprint_hash;
  INSERT INTO public.auto_staff_device_change_history
    (request_id,staff_id,organization_id,source,old_binding,requesting_device,remaining_before,remaining_after,created_at)
  VALUES (p_request_id,s.id,s.organization_id,p_source,
    jsonb_build_object('hash',s.device_fingerprint_hash,'label',s.device_label,'platform',s.device_platform,'boundAt',s.device_bound_at),
    device,remaining,remaining_after,stamp);
  RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',remaining_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_reset_device_binding_v2(p_username text, p_password text, p_source text, p_request_id uuid, p_expected_binding jsonb, p_device jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET lock_timeout TO '3s'
AS $function$
DECLARE
  s public.org_staff%ROWTYPE;
  h public.auto_staff_device_change_history%ROWTYPE;
  remaining integer;
  remaining_after integer;
  outcome text;
  stamp timestamptz;
  device jsonb;
  revision text;
BEGIN
  IF p_source IS NULL OR p_source NOT IN ('login', 'account_menu') OR p_request_id IS NULL
     OR jsonb_typeof(p_expected_binding) IS DISTINCT FROM 'object'
     OR NOT (p_expected_binding ?& ARRAY['staffId','hash','revision','version'])
     OR p_expected_binding->>'version' IS DISTINCT FROM '2'
     OR coalesce(p_expected_binding->>'revision','') !~ '^[0-9]+$'
     OR jsonb_typeof(p_device) IS DISTINCT FROM 'object'
     OR coalesce(p_device->>'fingerprintHash','') !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'Invalid device change request' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO s FROM public.org_staff WHERE username = btrim(p_username) FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'changed',false,'code','not_found','remainingChanges',null); END IF;
  SELECT xmin::text INTO revision FROM public.org_staff WHERE id=s.id;
  remaining := coalesce(s.device_changes_remaining, 5);
  IF NOT s.is_active THEN outcome := 'inactive';
  ELSIF p_source = 'account_menu' AND s.password IS DISTINCT FROM p_password THEN outcome := 'not_authorized';
  ELSIF s.id::text IS DISTINCT FROM p_expected_binding->>'staffId' THEN outcome := 'binding_conflict';
  END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',false,'changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Whitelist metadata: the history must never persist arbitrary credentials.
  device := jsonb_build_object('fingerprintHash',p_device->>'fingerprintHash',
    'label',left(p_device->>'label',255),'platform',left(p_device->>'platform',20),
    'appVersion',left(p_device->>'appVersion',50),'bindingVersion',2);
  SELECT * INTO h FROM public.auto_staff_device_change_history WHERE request_id = p_request_id;
  IF FOUND THEN
    IF h.staff_id <> s.id OR h.source <> p_source
       OR h.requesting_device->>'fingerprintHash' IS DISTINCT FROM device->>'fingerprintHash'
       OR h.old_binding->>'hash' IS DISTINCT FROM p_expected_binding->>'hash'
       OR h.old_binding->>'version' IS DISTINCT FROM '2'
       OR h.old_binding->>'revision' IS DISTINCT FROM p_expected_binding->>'revision' THEN
      RETURN jsonb_build_object('success',false,'changed',false,'code','binding_conflict','remainingChanges',remaining);
    END IF;
    RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',h.remaining_after);
  END IF;

  IF s.aka_agent_device_fingerprint_hash IS NULL THEN outcome := 'already_unbound';
  ELSIF p_source = 'account_menu' AND s.aka_agent_device_fingerprint_hash IS DISTINCT FROM device->>'fingerprintHash' THEN outcome := 'not_authorized';
  ELSIF s.aka_agent_device_fingerprint_hash IS DISTINCT FROM p_expected_binding->>'hash'
     OR revision IS DISTINCT FROM p_expected_binding->>'revision' THEN outcome := 'binding_conflict';
  ELSIF p_source = 'login' AND remaining <= 0 THEN outcome := 'quota_exhausted';
  END IF;
  stamp := clock_timestamp();
  IF outcome IS NULL AND p_source = 'login' AND EXISTS (
    SELECT 1 FROM public.auto_staff_device_presence
    WHERE staff_id = s.id AND ended_at IS NULL AND last_seen_at > stamp - interval '120 seconds'
  ) THEN outcome := 'device_online'; END IF;
  IF outcome IS NOT NULL THEN
    RETURN jsonb_build_object('success',outcome = 'already_unbound','changed',false,'code',outcome,'remainingChanges',remaining);
  END IF;

  -- Only the unauthenticated login flow consumes the device-change quota.
  remaining_after := remaining - CASE WHEN p_source = 'login' THEN 1 ELSE 0 END;
  UPDATE public.org_staff SET aka_agent_device_fingerprint_hash = NULL,
    device_changes_remaining = CASE WHEN p_source = 'login' THEN remaining_after ELSE s.device_changes_remaining END,
    updated_at = stamp
  WHERE id = s.id;
  INSERT INTO public.auto_staff_device_change_history
    (request_id,staff_id,organization_id,source,old_binding,requesting_device,remaining_before,remaining_after,created_at)
  VALUES (p_request_id,s.id,s.organization_id,p_source,
    jsonb_build_object('hash',s.aka_agent_device_fingerprint_hash,'revision',revision,'version',2),
    device,remaining,remaining_after,stamp);
  RETURN jsonb_build_object('success',true,'changed',true,'code','changed','remainingChanges',remaining_after);
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_save_automation_v205_internal(p_staff_id bigint, p_organization_id bigint, p_automation_id bigint, p_name text, p_source_campaign_id bigint, p_target_campaign_id bigint, p_data_type_code text, p_target_contact_group_id bigint, p_target_data_group_id bigint, p_schedule_mode text, p_delay_days integer, p_delay_hours integer, p_fixed_at timestamp with time zone, p_note text, p_is_active boolean, p_trigger_statuses jsonb, p_auth_username text DEFAULT NULL::text, p_auth_password text DEFAULT NULL::text, p_delay_value integer DEFAULT NULL::integer, p_delay_unit text DEFAULT NULL::text, p_daily_time time without time zone DEFAULT NULL::time without time zone, p_delay_exact_time time without time zone DEFAULT NULL::time without time zone, p_delay_exact_time_present boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_existing public.auto_automation%ROWTYPE;
  v_rule_id bigint;
  v_source_action_id text;
  v_schedule_mode text := lower(NULLIF(btrim(COALESCE(p_schedule_mode, '')), ''));
  v_delay_value integer := p_delay_value;
  v_delay_unit text := lower(NULLIF(btrim(COALESCE(p_delay_unit, '')), ''));
  v_effective_delay_exact_time time without time zone;
  v_status jsonb;
  v_previous_trigger_statuses jsonb := '[]'::jsonb;
  v_sub_status_json jsonb;
  v_sub_status_ids bigint[];
  v_status_mapping_id bigint;
  v_status_mapping_id_text text;
  v_action_code text;
  v_status_value text;
  v_semantic_status_id bigint;
  v_mapping record;
BEGIN
  -- Authentication must precede every tenant-scoped existence check.
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  IF p_target_campaign_id IS NULL AND p_target_data_group_id IS NULL THEN
    RAISE EXCEPTION 'automation_destination_required';
  END IF;

  IF p_target_campaign_id IS NOT NULL THEN
    -- The established campaign validator/save stack remains authoritative for
    -- campaign-only and dual-destination rules.
    PERFORM pg_advisory_xact_lock(hashtextextended(
      'auto_automation_graph:' || p_staff_id::text || ':' || p_organization_id::text,
      0
    ));
    IF p_target_data_group_id IS NOT NULL THEN
      PERFORM contact_group.id
      FROM public.auto_account_contact_groups AS contact_group
      WHERE contact_group.id = p_target_data_group_id
        AND contact_group.staff_id = p_staff_id
        AND contact_group.organization_id = p_organization_id
        AND contact_group.purpose = 'data_group'
        AND contact_group.is_delete = false
      FOR SHARE OF contact_group;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'invalid_target_data_group';
      END IF;
    END IF;
    RETURN public.aka_agent_save_automation_v201_campaign_internal(
      p_staff_id, p_organization_id, p_automation_id, p_name,
      p_source_campaign_id, p_target_campaign_id, p_data_type_code,
      p_target_contact_group_id, p_target_data_group_id, p_schedule_mode,
      p_delay_days, p_delay_hours, p_fixed_at, p_note, p_is_active,
      p_trigger_statuses, p_auth_username, p_auth_password, p_delay_value,
      p_delay_unit, p_daily_time, p_delay_exact_time,
      p_delay_exact_time_present
    );
  END IF;

  IF p_target_contact_group_id IS NOT NULL THEN
    RAISE EXCEPTION 'target_contact_group_requires_campaign';
  END IF;
  IF NULLIF(btrim(COALESCE(p_name, '')), '') IS NULL
    OR length(btrim(p_name)) > 200
  THEN
    RAISE EXCEPTION 'invalid_automation_name';
  END IF;
  IF length(COALESCE(p_note, '')) > 2000 THEN
    RAISE EXCEPTION 'invalid_automation_note';
  END IF;
  IF jsonb_typeof(COALESCE(p_trigger_statuses, 'null'::jsonb)) <> 'array'
    OR jsonb_array_length(p_trigger_statuses) = 0
    OR jsonb_array_length(p_trigger_statuses) > 100
  THEN
    RAISE EXCEPTION 'invalid_automation_trigger_statuses';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'auto_automation_graph:' || p_staff_id::text || ':' || p_organization_id::text,
    0
  ));

  IF NOT EXISTS (
    SELECT 1
    FROM public.org_staff AS staff
    WHERE staff.id = p_staff_id
      AND staff.organization_id = p_organization_id
      AND staff.is_active = true
  ) THEN
    RAISE EXCEPTION 'inactive_automation_staff';
  END IF;

  SELECT campaign.action_id
  INTO v_source_action_id
  FROM public.auto_campaigns AS campaign
  JOIN public.auto_campaign_actions AS campaign_action
    ON campaign_action.id = campaign.action_id
   AND campaign_action.is_active = true
   AND COALESCE(campaign_action.is_delete, false) = false
  JOIN public.auto_accounts AS account
    ON account.id = campaign.account_id
   AND account.staff_id = p_staff_id
   AND account.organization_id = p_organization_id
   AND COALESCE(account.is_delete, false) = false
  WHERE campaign.id = p_source_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
    AND COALESCE(campaign.is_delete, false) = false;
  IF v_source_action_id IS NULL THEN
    RAISE EXCEPTION 'invalid_source_campaign';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_automation_data_types AS data_type
    JOIN public.auto_campaign_action_data_types AS mapping
      ON mapping.data_type_code = data_type.code
     AND mapping.campaign_action_id = v_source_action_id
     AND mapping.can_source = true
     AND mapping.is_active = true
     AND mapping.is_delete = false
    WHERE data_type.code = p_data_type_code
      AND data_type.is_active = true
      AND data_type.is_delete = false
  ) THEN
    RAISE EXCEPTION 'source_campaign_data_type_not_supported';
  END IF;

  PERFORM contact_group.id
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_target_data_group_id
    AND contact_group.staff_id = p_staff_id
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR SHARE OF contact_group;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'invalid_target_data_group';
  END IF;

  IF v_schedule_mode NOT IN ('immediate', 'after_delay', 'daily_time', 'fixed_at')
    OR COALESCE(p_delay_days, 0) NOT BETWEEN 0 AND 3650
    OR COALESCE(p_delay_hours, 0) NOT BETWEEN 0 AND 23
  THEN
    RAISE EXCEPTION 'invalid_automation_schedule';
  END IF;

  -- Preserve the v176 compatibility contract for clients that still send only
  -- delay_days/delay_hours.
  IF v_schedule_mode = 'after_delay'
    AND v_delay_value IS NULL
    AND v_delay_unit IS NULL
    AND (
      COALESCE(p_delay_days, 0) > 0
      OR COALESCE(p_delay_hours, 0) > 0
    )
  THEN
    IF COALESCE(p_delay_hours, 0) = 0 THEN
      v_delay_value := COALESCE(p_delay_days, 0);
      v_delay_unit := 'day';
    ELSE
      v_delay_value := LEAST(
        (
          COALESCE(p_delay_days, 0) * 24
        ) + COALESCE(p_delay_hours, 0),
        87600
      );
      v_delay_unit := 'hour';
    END IF;
  END IF;

  IF v_schedule_mode = 'after_delay' THEN
    IF COALESCE(p_delay_exact_time_present, false) THEN
      v_effective_delay_exact_time := p_delay_exact_time;
    ELSIF p_automation_id IS NOT NULL THEN
      SELECT automation.delay_exact_time
      INTO v_effective_delay_exact_time
      FROM public.auto_automation AS automation
      WHERE automation.id = p_automation_id
        AND automation.staff_id = p_staff_id
        AND automation.organization_id = p_organization_id
        AND automation.is_delete = false;
    END IF;
  END IF;

  IF v_schedule_mode = 'immediate' AND (
    COALESCE(p_delay_days, 0) <> 0
    OR COALESCE(p_delay_hours, 0) <> 0
    OR v_delay_value IS NOT NULL OR v_delay_unit IS NOT NULL
    OR p_daily_time IS NOT NULL OR p_fixed_at IS NOT NULL
    OR v_effective_delay_exact_time IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'invalid_immediate_schedule';
  ELSIF v_schedule_mode = 'after_delay' AND (
    v_delay_value IS NULL
    OR v_delay_unit NOT IN ('minute', 'hour', 'day')
    OR v_delay_value <= 0
    OR (v_delay_unit = 'minute' AND v_delay_value > 5256000)
    OR (v_delay_unit = 'hour' AND v_delay_value > 87600)
    OR (v_delay_unit = 'day' AND v_delay_value > 3650)
    OR p_daily_time IS NOT NULL OR p_fixed_at IS NOT NULL
    OR (
      v_effective_delay_exact_time IS NOT NULL
      AND (
        v_effective_delay_exact_time >= time '24:00'
        OR EXTRACT(SECOND FROM v_effective_delay_exact_time) <> 0
      )
    )
  ) THEN
    RAISE EXCEPTION 'invalid_delay_schedule';
  ELSIF v_schedule_mode = 'daily_time' AND (
    COALESCE(p_delay_days, 0) <> 0
    OR COALESCE(p_delay_hours, 0) <> 0
    OR v_delay_value IS NOT NULL OR v_delay_unit IS NOT NULL
    OR p_daily_time IS NULL
    OR EXTRACT(SECOND FROM p_daily_time) <> 0
    OR p_fixed_at IS NOT NULL
    OR v_effective_delay_exact_time IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'invalid_daily_time_schedule';
  ELSIF v_schedule_mode = 'fixed_at' AND (
    p_fixed_at IS NULL
    OR COALESCE(p_delay_days, 0) <> 0
    OR COALESCE(p_delay_hours, 0) <> 0
    OR v_delay_value IS NOT NULL OR v_delay_unit IS NOT NULL
    OR p_daily_time IS NOT NULL
    OR v_effective_delay_exact_time IS NOT NULL
    OR (COALESCE(p_is_active, false) AND p_fixed_at <= clock_timestamp())
  ) THEN
    RAISE EXCEPTION 'invalid_fixed_schedule';
  END IF;

  IF p_automation_id IS NULL THEN
    INSERT INTO public.auto_automation (
      automation_action_id, name, source_campaign_id, target_campaign_id,
      data_type_code, target_contact_group_id, target_data_group_id,
      schedule_mode, delay_days, delay_hours, delay_value, delay_unit,
      delay_exact_time, daily_time, fixed_at, note, is_active, activated_at,
      config_version, is_delete, staff_id, organization_id
    ) VALUES (
      'campaign_detail_route', btrim(p_name), p_source_campaign_id, NULL,
      p_data_type_code, NULL, p_target_data_group_id,
      v_schedule_mode, COALESCE(p_delay_days, 0), COALESCE(p_delay_hours, 0),
      v_delay_value, v_delay_unit, v_effective_delay_exact_time, p_daily_time,
      p_fixed_at, NULLIF(btrim(COALESCE(p_note, '')), ''),
      COALESCE(p_is_active, false),
      CASE WHEN COALESCE(p_is_active, false) THEN clock_timestamp() ELSE NULL END,
      1, false, p_staff_id, p_organization_id
    )
    RETURNING id INTO v_rule_id;
  ELSE
    SELECT *
    INTO v_existing
    FROM public.auto_automation AS automation
    WHERE automation.id = p_automation_id
      AND automation.staff_id = p_staff_id
      AND automation.organization_id = p_organization_id
      AND automation.is_delete = false
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'automation_not_found';
    END IF;

    UPDATE public.auto_automation AS automation
    SET name = btrim(p_name),
        source_campaign_id = p_source_campaign_id,
        target_campaign_id = NULL,
        data_type_code = p_data_type_code,
        target_contact_group_id = NULL,
        target_data_group_id = p_target_data_group_id,
        schedule_mode = v_schedule_mode,
        delay_days = COALESCE(p_delay_days, 0),
        delay_hours = COALESCE(p_delay_hours, 0),
        delay_value = v_delay_value,
        delay_unit = v_delay_unit,
        delay_exact_time = v_effective_delay_exact_time,
        daily_time = p_daily_time,
        fixed_at = p_fixed_at,
        note = NULLIF(btrim(COALESCE(p_note, '')), ''),
        is_active = COALESCE(p_is_active, false),
        activated_at = CASE
          WHEN COALESCE(p_is_active, false) THEN clock_timestamp()
          ELSE automation.activated_at
        END,
        config_version = automation.config_version + 1,
        updated_at = clock_timestamp()
    WHERE automation.id = v_existing.id
    RETURNING automation.id INTO v_rule_id;

    SELECT COALESCE(jsonb_agg(to_jsonb(trigger_status)),'[]'::jsonb)
    INTO v_previous_trigger_statuses FROM public.auto_automation_trigger_statuses trigger_status
    WHERE trigger_status.automation_id=v_rule_id;
    DELETE FROM public.auto_automation_trigger_statuses AS trigger_status
    WHERE trigger_status.automation_id = v_rule_id;
  END IF;

  FOR v_status IN
    SELECT item.value
    FROM jsonb_array_elements(p_trigger_statuses) AS item(value)
  LOOP
    IF jsonb_typeof(v_status) <> 'object' THEN
      RAISE EXCEPTION 'invalid_automation_trigger_status';
    END IF;

    v_status_mapping_id := NULL;
    v_status_mapping_id_text := NULLIF(btrim(COALESCE(
      v_status ->> 'statusMappingId',
      v_status ->> 'status_mapping_id',
      ''
    )), '');

    IF v_status_mapping_id_text IS NOT NULL THEN
      IF v_status_mapping_id_text !~ '^[1-9][0-9]*$' THEN
        RAISE EXCEPTION 'invalid_automation_trigger_status';
      END IF;
      v_status_mapping_id := v_status_mapping_id_text::bigint;
    ELSE
      v_action_code := NULLIF(btrim(COALESCE(
        v_status ->> 'actionCode', v_status ->> 'action_code', ''
      )), '');
      v_status_value := NULLIF(btrim(COALESCE(
        v_status ->> 'statusValue', v_status ->> 'status_value',
        v_status ->> 'status', ''
      )), '');
      IF v_status_value IS NULL OR length(v_status_value) > 200 THEN
        RAISE EXCEPTION 'invalid_automation_trigger_status_value';
      END IF;
      IF v_action_code IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.auto_account_actions AS account_action
        WHERE account_action.code = v_action_code
          AND account_action.is_active = true
          AND account_action.is_delete = false
      ) THEN
        RAISE EXCEPTION 'invalid_automation_trigger_action_code';
      END IF;

      SELECT status_mapping.id
      INTO v_status_mapping_id
      FROM public.auto_campaign_action_detail_statuses AS status_mapping
      WHERE status_mapping.campaign_action_id = v_source_action_id
        AND status_mapping.action_code IS NOT DISTINCT FROM v_action_code
        AND lower(status_mapping.status_value) = lower(v_status_value)
        AND status_mapping.is_active = true
        AND status_mapping.is_delete = false
      ORDER BY status_mapping.id
      LIMIT 1;

      IF v_status_mapping_id IS NULL THEN
        SELECT status_catalog.id
        INTO v_semantic_status_id
        FROM public.auto_status AS status_catalog
        WHERE status_catalog.component_type = 'campaign_detail'
          AND status_catalog.is_active = true
          AND status_catalog.is_delete = false
          AND lower(status_catalog.name) = lower(v_status_value)
        ORDER BY status_catalog.sort_order, status_catalog.id
        LIMIT 1;

        INSERT INTO public.auto_campaign_action_detail_statuses (
          campaign_action_id, action_code, status_id, status_value, label,
          is_active, is_delete, updated_at
        ) VALUES (
          v_source_action_id, v_action_code, v_semantic_status_id,
          v_status_value, v_status_value, true, false, clock_timestamp()
        )
        ON CONFLICT DO NOTHING;

        UPDATE public.auto_campaign_action_detail_statuses AS status_mapping
        SET is_active = true,
            label = v_status_value,
            status_id = COALESCE(
              status_mapping.status_id,
              v_semantic_status_id
            ),
            updated_at = clock_timestamp()
        WHERE status_mapping.campaign_action_id = v_source_action_id
          AND status_mapping.action_code IS NOT DISTINCT FROM v_action_code
          AND lower(status_mapping.status_value) = lower(v_status_value)
          AND status_mapping.is_delete = false;

        SELECT status_mapping.id
        INTO v_status_mapping_id
        FROM public.auto_campaign_action_detail_statuses AS status_mapping
        WHERE status_mapping.campaign_action_id = v_source_action_id
          AND status_mapping.action_code IS NOT DISTINCT FROM v_action_code
          AND lower(status_mapping.status_value) = lower(v_status_value)
          AND status_mapping.is_active = true
          AND status_mapping.is_delete = false
        ORDER BY status_mapping.id
        LIMIT 1;
      END IF;
    END IF;

    SELECT
      status_mapping.id,
      status_mapping.action_code,
      status_mapping.status_value
    INTO v_mapping
    FROM public.auto_campaign_action_detail_statuses AS status_mapping
    WHERE status_mapping.id = v_status_mapping_id
      AND status_mapping.campaign_action_id = v_source_action_id
      AND status_mapping.is_active = true
      AND status_mapping.is_delete = false;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'invalid_automation_trigger_status';
    END IF;

    -- Missing field from an old client preserves the same saved condition.
    -- Explicit JSON null clears the filter; an empty or malformed array fails.
    v_sub_status_json:=CASE
      WHEN v_status ? 'subStatusIds' THEN v_status->'subStatusIds'
      WHEN v_status ? 'sub_status_ids' THEN v_status->'sub_status_ids'
      ELSE (SELECT p->'sub_status_ids' FROM jsonb_array_elements(v_previous_trigger_statuses) p
        WHERE (p->>'status_mapping_id')::bigint=v_mapping.id LIMIT 1) END;
    v_sub_status_ids:=NULL;
    IF v_sub_status_json IS NOT NULL AND v_sub_status_json<>'null'::jsonb THEN
      IF jsonb_typeof(v_sub_status_json)<>'array' THEN RAISE EXCEPTION 'invalid_automation_sub_status_ids'; END IF;
      IF jsonb_array_length(v_sub_status_json)=0 OR EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_sub_status_json) i
        WHERE jsonb_typeof(i)<>'number' OR i::text !~ '^[1-9][0-9]*$'
      ) THEN RAISE EXCEPTION 'invalid_automation_sub_status_ids'; END IF;
      SELECT array_agg(DISTINCT i::text::bigint ORDER BY i::text::bigint) INTO v_sub_status_ids
      FROM jsonb_array_elements(v_sub_status_json) i;
    END IF;
    INSERT INTO public.auto_automation_trigger_statuses (
      automation_id, status_mapping_id, action_code, status_value, sub_status_ids
    ) VALUES (
      v_rule_id, v_mapping.id, v_mapping.action_code, v_mapping.status_value, v_sub_status_ids
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  -- A wildcard already covers specifics with the same semantic status.
  DELETE FROM public.auto_automation_trigger_statuses AS specific
  USING public.auto_campaign_action_detail_statuses AS specific_mapping,
    public.auto_automation_trigger_statuses AS wildcard,
    public.auto_campaign_action_detail_statuses AS wildcard_mapping
  WHERE specific.automation_id = v_rule_id
    AND specific.status_mapping_id = specific_mapping.id
    AND specific.action_code IS NOT NULL
    AND wildcard.automation_id = specific.automation_id
    AND wildcard.action_code IS NULL
    AND wildcard.status_mapping_id = wildcard_mapping.id
    AND (wildcard.sub_status_ids IS NULL OR (
      specific.sub_status_ids IS NOT NULL AND specific.sub_status_ids <@ wildcard.sub_status_ids
    ))
    AND (
      lower(wildcard.status_value) = lower(specific.status_value)
      OR (
        wildcard_mapping.status_id IS NOT NULL
        AND specific_mapping.status_id IS NOT NULL
        AND wildcard_mapping.status_id = specific_mapping.status_id
      )
    );

  IF NOT EXISTS (
    SELECT 1 FROM public.auto_automation_trigger_statuses AS trigger_status
    WHERE trigger_status.automation_id = v_rule_id
  ) THEN
    RAISE EXCEPTION 'automation_trigger_status_required';
  END IF;

  RETURN public.auto_automation_to_json(
    v_rule_id, p_staff_id, p_organization_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_sheet_identity(p_type text, p_row jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v text; v_id text; v_path text;
BEGIN
  IF p_type='phone' THEN
    -- Same precedence as ingest/campaign extraction: primary field, legacy
    -- extra_data, then UID only for a contact whose identity is a phone/email.
    v:=public.aka_agent_internal_normalize_phone(COALESCE(
      NULLIF(p_row->>'phone',''),NULLIF(p_row->'extra_data'->>'phone',''),
      CASE WHEN p_row->>'contact_type'='phone' THEN p_row->>'uid' END,''));
    RETURN CASE WHEN v ~ '^0[35789][0-9]{8}$' THEN v ELSE NULL END;
  ELSIF p_type='email' THEN
    v:=lower(btrim(COALESCE(NULLIF(p_row->>'email',''),NULLIF(p_row->'extra_data'->>'email',''),
      CASE WHEN p_row->>'contact_type'='email' THEN p_row->>'uid' END,'')));
    RETURN CASE WHEN length(v)<=254 AND v ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN v ELSE NULL END;
  ELSIF p_type='facebook_search_keyword' THEN
    RETURN NULLIF(lower(regexp_replace(btrim(COALESCE(p_row->>'uid','')),'[[:space:]]+',' ','g')),'');
  ELSIF p_type='zalo_person' THEN
    v:=btrim(COALESCE(p_row->>'uid','')); RETURN CASE WHEN v ~ '^[0-9]+$' AND length(v)<=100 THEN v ELSE NULL END;
  ELSIF p_type='zalo_group' THEN
    v:=COALESCE(NULLIF(p_row->>'url',''),p_row->>'uid','');
    v_id:=substring(v from '^(?:https?://)?(?:www\.)?(?:zalo\.me/g/|zaloapp\.com/qr/g/)([A-Za-z0-9_-]+)(?:[/?#].*)?$');
    RETURN CASE WHEN v_id IS NOT NULL THEN 'zalo.me/g/'||v_id ELSE NULL END;
  ELSIF p_type IN ('facebook_person','facebook_group','facebook_page','facebook_post_url') THEN
    -- Existing post contacts may carry a numeric UID as well as the post URL.
    -- Sheet rows map the URL, so both sides must choose that same identity.
    IF p_type='facebook_post_url' THEN
      v:=COALESCE(NULLIF(btrim(p_row->>'url'),''),btrim(p_row->>'uid'),'');
    ELSE
      v:=btrim(COALESCE(NULLIF(p_row->>'uid',''),p_row->>'url',''));
    END IF;
    IF v ~ '^[0-9]+$' AND p_type<>'facebook_post_url' THEN RETURN v; END IF;
    IF v !~* '^(https?://)?(www\.|m\.|mbasic\.)?(facebook\.com|fb\.com)/[^[:space:]]+$' THEN RETURN NULL; END IF;
    v:=regexp_replace(v,'^(https?://)?(www\.|m\.|mbasic\.)?(facebook\.com|fb\.com)/','','i');
    v:=split_part(v,'#',1); v_path:=regexp_replace(split_part(v,'?',1),'/$','');
    IF p_type='facebook_group' THEN
      v_id:=substring(v_path from '^groups/([^/]+)'); RETURN lower(v_id);
    ELSIF p_type='facebook_post_url' THEN
      -- Support raw legacy contact URLs as well as the mapper's canonical URL.
      IF v_path ~ '^groups/[^/]+' AND v ~ '[?&]multi_permalinks=' THEN
        v_id:=substring(v from '[?&]multi_permalinks=([A-Za-z0-9_-]+)(?:&|$)');
        RETURN CASE WHEN v_id IS NOT NULL THEN 'post:'||v_id ELSE NULL END;
      END IF;
      IF v_path IN ('watch','watch/live','video.php') THEN
        v_id:=substring(v from '[?&]v=([A-Za-z0-9_-]+)(?:&|$)');
        RETURN CASE WHEN v_id IS NOT NULL THEN 'post:'||v_id ELSE NULL END;
      END IF;
      -- A group landing page has no post identity (including links already
      -- stripped by an older client); never import it as a valid post.
      IF v_path ~ '^groups/[^/]+$' THEN RETURN NULL; END IF;
      -- Opaque pfbid values are case-sensitive; never truncate to a numeric
      -- prefix or collapse every story.php/permalink.php URL to one key.
      v_id:=substring(v from '[?&](?:story_fbid|fbid)=([A-Za-z0-9_-]+)(?:&|$)');
      IF v_id IS NOT NULL THEN RETURN 'post:'||v_id; END IF;
      v_id:=substring(v_path from '(?:^|/)(?:posts|permalink|videos|reel)/([A-Za-z0-9_-]+)(?:/|$)');
      IF v_id IS NOT NULL THEN RETURN 'post:'||v_id; END IF;
      RETURN lower(v_path);
    ELSE
      -- Reuse the campaign canonicalizer for /people/name/UID and /pages/name/UID.
      -- The host was validated and stripped above, including the fb.com alias.
      RETURN NULLIF(public.aka_agent_internal_normalize_facebook_identity('https://www.facebook.com/'||v),'');
    END IF;
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_snapshot_data_group_to_direct_campaign_v205_internal(p_staff_id bigint, p_organization_id bigint, p_request_id text, p_campaign_id bigint, p_group_id bigint, p_campaign_schedule timestamp with time zone, p_campaign_status text, p_auth_username text, p_auth_password text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET statement_timeout TO '60s'
AS $function$
DECLARE
  v_campaign public.auto_campaigns%ROWTYPE;
  v_group public.auto_account_contact_groups%ROWTYPE;
  v_member public.auto_account_contact_group_members%ROWTYPE;
  v_contact public.auto_account_contacts%ROWTYPE;
  v_batch public.auto_data_ingest_batches%ROWTYPE;
  v_action text;
  v_platform text;
  v_contact_type text;
  v_name text;
  v_uid text;
  v_url text;
  v_phone text;
  v_email text;
  v_input_uid text;
  v_input_phone text;
  v_input_email text;
  v_target_value text;
  v_identity_value text;
  v_uid_identity text;
  v_url_identity text;
  v_allow_alias_resolution boolean;
  v_target_kind text;
  v_scope text;
  v_candidate_key text;
  v_canonical_key text;
  v_aliases text[];
  v_mapped_keys text[];
  v_payload jsonb;
  v_input_id bigint;
  v_inserted_row boolean;
  v_info1 text;
  v_info2 text;
  v_info3 text;
  v_info4 text;
  v_info5 text;
  v_phone_carrier text;
  v_request_hash text;
  v_result jsonb;
  v_active integer := 0;
  v_inserted integer := 0;
  v_existing integer := 0;
  v_incompatible integer := 0;
  v_conflict integer := 0;
  v_account_runtime_target text;
  v_runtime_target text := lower(btrim(COALESCE(
    NULLIF(current_setting('aka_agent.zalo_runtime_target', true), ''),
    'desktop'
  )));
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id, p_organization_id, p_auth_username, p_auth_password
  );

  IF p_staff_id IS NULL OR p_staff_id <= 0
    OR p_organization_id IS NULL OR p_organization_id <= 0
    OR p_campaign_id IS NULL OR p_campaign_id <= 0
    OR p_group_id IS NULL OR p_group_id <= 0
    OR p_campaign_schedule IS NULL
    OR p_campaign_status IS NULL
    OR p_campaign_status NOT IN ('chờ xử lý', 'tạm dừng')
    OR NULLIF(btrim(COALESCE(p_request_id, '')), '') IS NULL
    OR length(btrim(p_request_id)) > 500
  THEN
    RAISE EXCEPTION 'invalid_direct_campaign_group_snapshot';
  END IF;

  v_request_hash := md5(jsonb_build_object(
    'operation', 'snapshot_campaign',
    'campaignId', p_campaign_id,
    'groupId', p_group_id,
    'campaignSchedule', to_char(
      p_campaign_schedule AT TIME ZONE 'UTC',
      'YYYY-MM-DD"T"HH24:MI:SS.US'
    ),
    'campaignStatus', p_campaign_status
  )::text);

  -- Return a committed response before consulting mutable campaign/group state.
  -- This makes response-loss retries stable even if the group changes later.
  SELECT batch.*
  INTO v_batch
  FROM public.auto_data_ingest_batches AS batch
  WHERE batch.staff_id = p_staff_id
    AND batch.organization_id = p_organization_id
    AND batch.request_id = btrim(p_request_id)
  FOR UPDATE;
  IF FOUND THEN
    IF v_batch.operation <> 'snapshot_campaign'
      OR v_batch.group_id IS DISTINCT FROM p_group_id
      OR v_batch.request_hash <> v_request_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  -- Match the shared Data Group lock hierarchy (group -> campaign) used by
  -- ingest/bind/delete; do not invert those locks during live intake.
  SELECT contact_group.*
  INTO v_group
  FROM public.auto_account_contact_groups AS contact_group
  WHERE contact_group.id = p_group_id
    AND private.can_read_data_group(contact_group.id,p_staff_id,p_organization_id)
    AND contact_group.organization_id = p_organization_id
    AND contact_group.purpose = 'data_group'
    AND contact_group.is_delete = false
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'data_group_not_found'; END IF;

  -- Keep the shared Data Group hierarchy: batch -> group -> barrier ->
  -- campaign -> account/input. Bind/reactivate/router paths take the same
  -- group-before-barrier order.
  PERFORM public.aka_agent_lock_campaign_input_serialization(p_campaign_id);

  SELECT campaign.*
  INTO v_campaign
  FROM public.auto_campaigns AS campaign
  WHERE campaign.id = p_campaign_id
    AND campaign.staff_id = p_staff_id
    AND campaign.organization_id = p_organization_id
  FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_campaign.is_delete, false) THEN
    RAISE EXCEPTION 'campaign_not_found';
  END IF;
  IF v_campaign.data_target_source_mode IS DISTINCT FROM 'direct'
    OR v_campaign.provisioning_state IS DISTINCT FROM 'ready'
    OR v_campaign.status = 'đang chạy'
    OR EXISTS (
      SELECT 1
      FROM public.auto_campaign_data_group_sources AS source
      WHERE source.campaign_id = v_campaign.id
    )
  THEN
    RAISE EXCEPTION 'campaign_not_direct_snapshot_eligible';
  END IF;
  IF v_campaign.action_id NOT IN (
    'facebook_group_post', 'facebook_join_group', 'facebook_message_uid',
    'facebook_find_data_group', 'facebook_find_data_search',
    'facebook_comment_seeding', 'facebook_comment_seeding_post',
    'zalo_message_phone', 'zalo_join_group_link', 'email_send',
    'facebook_message_friend', 'facebook_group_invite', 'facebook_page_post',
    'zalo_message_friend', 'zalo_message_group_member',
    'zalo_message_remarketing_customer', 'zalo_message_group',
    'zalo_add_group_member'
  ) THEN
    RAISE EXCEPTION 'data_group_campaign_action_incompatible';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.auto_campaign_actions AS action
    WHERE action.id = v_campaign.action_id
      AND action.is_active = true
      AND COALESCE(action.is_delete, false) = false
  ) THEN
    RAISE EXCEPTION 'campaign_action_inactive';
  END IF;
  -- Campaign is already locked above. Lock account second so campaign claims
  -- and subtype conversion cannot race this runtime ownership decision.
  SELECT CASE
    WHEN lower(btrim(COALESCE(account.flatform_type, ''))) = 'zalo'
      AND COALESCE(account.is_zalo_show_web, false) = false
      AND COALESCE(account.is_zalo_server, false) = true
    THEN 'server'
    ELSE 'desktop'
  END
  INTO v_account_runtime_target
  FROM public.auto_accounts AS account
  WHERE account.id = v_campaign.account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = p_organization_id)
    AND COALESCE(account.is_delete, false) = false
  FOR SHARE OF account;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'campaign_account_not_found';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server')
    OR v_runtime_target IS DISTINCT FROM v_account_runtime_target
  THEN
    RAISE EXCEPTION 'direct_campaign_runtime_not_owner';
  END IF;

  INSERT INTO public.auto_data_ingest_batches (
    request_id, operation, group_id, kind, source_name, request_hash,
    status, staff_id, organization_id
  ) VALUES (
    btrim(p_request_id), 'snapshot_campaign', v_group.id, 'manual',
    'Snapshot Nhóm data: ' || v_group.name, v_request_hash,
    'processing', p_staff_id, p_organization_id
  )
  ON CONFLICT (staff_id, organization_id, request_id) DO NOTHING
  RETURNING * INTO v_batch;

  IF NOT FOUND THEN
    SELECT batch.*
    INTO v_batch
    FROM public.auto_data_ingest_batches AS batch
    WHERE batch.staff_id = p_staff_id
      AND batch.organization_id = p_organization_id
      AND batch.request_id = btrim(p_request_id)
    FOR UPDATE;
    IF v_batch.operation <> 'snapshot_campaign'
      OR v_batch.group_id IS DISTINCT FROM v_group.id
      OR v_batch.request_hash <> v_request_hash
    THEN
      RAISE EXCEPTION 'data_group_request_id_conflict';
    END IF;
    IF v_batch.result IS NOT NULL THEN RETURN v_batch.result; END IF;
    RAISE EXCEPTION 'data_group_request_incomplete';
  END IF;

  v_action := btrim(COALESCE(v_campaign.action_id, ''));

  FOR v_member IN
    SELECT member.*
    FROM public.auto_account_contact_group_members AS member
    WHERE member.group_id = v_group.id
      AND member.is_delete = false
    ORDER BY member.id
  LOOP
    v_active := v_active + 1;
    v_input_uid := NULL;
    v_input_phone := NULL;
    v_input_email := NULL;
    v_target_value := NULL;
    v_identity_value := NULL;
    v_uid_identity := NULL;
    v_url_identity := NULL;
    v_target_kind := NULL;
    v_scope := NULL;
    v_candidate_key := NULL;
    v_canonical_key := NULL;
    v_aliases := '{}'::text[];
    v_mapped_keys := '{}'::text[];
    v_allow_alias_resolution := false;
    v_input_id := NULL;
    v_inserted_row := false;

    IF NOT (
      -- v228: valid-phone routes ignore all source semantic and contact
      -- metadata constraints; UID-only add-member still uses the old guard.
      v_action IN ('zalo_message_phone', 'zalo_add_group_member')
      AND public.aka_agent_data_group_membership_has_valid_phone(
        v_member.id, v_group.id
      )
    ) AND NOT public.aka_agent_data_group_membership_semantic_compatible(
      v_member.id, v_action, v_group.id
    ) THEN
      v_incompatible := v_incompatible + 1;
      CONTINUE;
    END IF;

    SELECT contact.*
    INTO v_contact
    FROM public.auto_account_contacts AS contact
    WHERE contact.id = v_member.contact_id
      AND contact.staff_id = v_group.staff_id
      AND contact.organization_id = p_organization_id
      AND COALESCE(contact.is_delete, false) = false;
    IF NOT FOUND THEN
      v_incompatible := v_incompatible + 1;
      CONTINUE;
    END IF;

    v_platform := lower(btrim(COALESCE(v_contact.flatform_type, '')));
    v_contact_type := lower(btrim(COALESCE(v_contact.contact_type, '')));
    v_name := NULLIF(btrim(COALESCE(v_contact.name, '')), '');
    v_uid := NULLIF(btrim(COALESCE(v_contact.uid, '')), '');
    v_url := NULLIF(btrim(COALESCE(v_contact.url, '')), '');
    v_phone := public.aka_agent_internal_normalize_phone(COALESCE(
      NULLIF(v_contact.phone, ''),
      NULLIF(v_contact.extra_data ->> 'phone', ''),
      CASE WHEN v_contact_type = 'phone' THEN v_contact.uid ELSE NULL END,
      ''
    ));
    v_phone := NULLIF(v_phone, '');
    v_email := NULLIF(lower(btrim(COALESCE(
      NULLIF(v_contact.email, ''),
      NULLIF(v_contact.extra_data ->> 'email', ''),
      CASE WHEN v_contact_type = 'email' THEN v_contact.uid ELSE NULL END,
      ''
    ))), '');
    IF v_email IS NOT NULL AND (
      v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
      OR length(v_email) > 254
    ) THEN
      v_email := NULL;
    END IF;
    v_info1 := NULLIF(v_contact.extra_data ->> 'info1', '');
    v_info2 := NULLIF(v_contact.extra_data ->> 'info2', '');
    v_info3 := NULLIF(v_contact.extra_data ->> 'info3', '');
    v_info4 := NULLIF(v_contact.extra_data ->> 'info4', '');
    v_info5 := NULLIF(v_contact.extra_data ->> 'info5', '');
    v_phone_carrier := COALESCE(
      NULLIF(v_contact.extra_data ->> 'phoneCarrier', ''),
      NULLIF(v_contact.extra_data ->> 'phone_carrier', '')
    );

    IF v_action IN ('facebook_group_post', 'facebook_join_group', 'facebook_find_data_group') THEN
      -- v227: snapshot Facebook routes use semantic type plus UID/URL only.
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'facebook_group'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action = 'facebook_message_uid' THEN
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'facebook_person'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action = 'facebook_find_data_search' THEN
      v_target_value := v_uid;
      v_target_kind := 'facebook_search'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action IN ('facebook_comment_seeding', 'facebook_comment_seeding_post') THEN
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := CASE WHEN v_action = 'facebook_comment_seeding_post'
        THEN 'facebook_post' ELSE 'facebook_comment_target' END;
      v_scope := 'portable'; v_input_uid := v_target_value;
    ELSIF v_action = 'zalo_message_phone' THEN
      IF v_phone IS NULL THEN v_incompatible := v_incompatible + 1; CONTINUE; END IF;
      v_target_value := v_phone; v_target_kind := 'phone'; v_scope := 'portable';
      v_input_phone := v_phone;
    ELSIF v_action = 'zalo_join_group_link' THEN
      IF v_platform <> 'zalo' OR v_contact_type <> 'group' THEN
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'zalo_group_link'; v_scope := 'portable';
      v_input_uid := v_target_value;
    ELSIF v_action = 'email_send' THEN
      IF v_email IS NULL THEN v_incompatible := v_incompatible + 1; CONTINUE; END IF;
      v_target_value := v_email; v_target_kind := 'email'; v_scope := 'portable';
      v_input_email := v_email;
    ELSIF v_action IN ('facebook_message_friend', 'facebook_group_invite') THEN
      -- v226: Facebook UID/URL targets do not inherit source-account or
      -- is_friend restrictions from scan metadata.
      v_target_value := COALESCE(v_url, v_uid);
      v_target_kind := 'facebook_person';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_target_value;
    ELSIF v_action = 'facebook_page_post' THEN
      -- v226: Page ID/URL validity is sufficient for a Facebook target.
      v_target_value := COALESCE(v_uid, v_url);
      v_target_kind := 'facebook_page';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_target_value;
    ELSIF v_action IN (
      'zalo_message_friend', 'zalo_message_group_member',
      'zalo_message_remarketing_customer'
    ) THEN
      IF v_platform <> 'zalo' OR v_contact_type <> 'person'
        OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id
        OR (v_action = 'zalo_message_friend' AND v_contact.is_friend IS DISTINCT FROM true)
      THEN
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
      v_target_value := v_uid; v_target_kind := 'zalo_person';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_uid;
    ELSIF v_action = 'zalo_message_group' THEN
      IF v_platform <> 'zalo' OR v_contact_type <> 'group'
        OR v_contact.account_id IS DISTINCT FROM v_campaign.account_id
        OR v_contact.is_joined IS DISTINCT FROM true
      THEN
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
      v_target_value := v_uid; v_target_kind := 'zalo_group';
      v_scope := 'bound:' || v_campaign.account_id::text;
      v_input_uid := v_uid;
    ELSIF v_action = 'zalo_add_group_member' THEN
      IF v_phone IS NOT NULL THEN
        v_target_value := v_phone; v_target_kind := 'phone'; v_scope := 'portable';
        v_input_phone := v_phone; v_input_uid := '';
      ELSIF v_platform = 'zalo' AND v_contact_type = 'person'
        AND v_uid IS NOT NULL
        AND v_contact.account_id IS NOT DISTINCT FROM v_campaign.account_id
      THEN
        v_target_value := v_uid; v_target_kind := 'zalo_person';
        v_scope := 'bound:' || v_campaign.account_id::text;
        v_input_uid := v_uid;
      ELSE
        v_incompatible := v_incompatible + 1; CONTINUE;
      END IF;
    ELSE
      v_incompatible := v_incompatible + 1; CONTINUE;
    END IF;

    IF NULLIF(v_target_value, '') IS NULL THEN
      v_incompatible := v_incompatible + 1; CONTINUE;
    END IF;

    IF v_target_kind LIKE 'facebook_%' THEN
      v_uid_identity := CASE WHEN v_uid IS NULL THEN NULL
        ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_uid), '') END;
      v_url_identity := CASE WHEN v_url IS NULL THEN NULL
        ELSE NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_url), '') END;
      v_identity_value := COALESCE(
        v_uid_identity,
        v_url_identity,
        NULLIF(public.aka_agent_internal_normalize_facebook_identity(v_target_value), '')
      );
      v_allow_alias_resolution := true;
    ELSIF v_target_kind = 'email' THEN
      v_identity_value := lower(v_target_value);
    ELSE
      v_identity_value := v_target_value;
    END IF;
    IF NULLIF(v_identity_value, '') IS NULL THEN
      v_incompatible := v_incompatible + 1; CONTINUE;
    END IF;

    v_candidate_key := v_scope || ':' || v_target_kind || ':' || v_identity_value;
    v_aliases := array_append(v_aliases, v_candidate_key);
    IF v_target_kind LIKE 'facebook_%' AND v_uid_identity IS NOT NULL THEN
      v_aliases := array_append(
        v_aliases, v_scope || ':' || v_target_kind || ':' || v_uid_identity
      );
    END IF;
    IF v_target_kind LIKE 'facebook_%' AND v_url_identity IS NOT NULL THEN
      v_aliases := array_append(
        v_aliases, v_scope || ':' || v_target_kind || ':' || v_url_identity
      );
    END IF;

    SELECT COALESCE(array_agg(DISTINCT alias.canonical_target_key), '{}'::text[])
    INTO v_mapped_keys
    FROM public.auto_campaign_input_target_aliases AS alias
    WHERE alias.campaign_id = v_campaign.id
      AND alias.alias_key = ANY(v_aliases);

    IF cardinality(v_mapped_keys) > 1
      OR (
        cardinality(v_mapped_keys) = 1
        AND NOT v_allow_alias_resolution
        AND v_mapped_keys[1] IS DISTINCT FROM v_candidate_key
      )
    THEN
      UPDATE public.auto_campaign_input_target_aliases AS alias
      SET conflict_count = alias.conflict_count + 1,
          last_conflict_at = now(),
          last_conflict_payload = jsonb_build_object(
            'membershipId', v_member.id,
            'candidateCanonicalKey', v_candidate_key,
            'mappedCanonicalKeys', to_jsonb(v_mapped_keys),
            'aliases', to_jsonb(v_aliases),
            'snapshotBatchId', v_batch.id
          ),
          updated_at = now()
      WHERE alias.campaign_id = v_campaign.id
        AND alias.alias_key = ANY(v_aliases);
      v_conflict := v_conflict + 1;
      CONTINUE;
    END IF;

    v_canonical_key := CASE
      WHEN v_allow_alias_resolution AND cardinality(v_mapped_keys) = 1
        THEN v_mapped_keys[1]
      ELSE v_candidate_key
    END;
    v_payload := jsonb_strip_nulls(jsonb_build_object(
      'name', COALESCE(v_name, v_target_value),
      'phone', v_input_phone,
      'phone_carrier', v_phone_carrier,
      'uid', v_input_uid,
      'email', v_input_email,
      'info1', v_info1,
      'info2', v_info2,
      'info3', v_info3,
      'info4', v_info4,
      'info5', v_info5,
      'contact_id', v_contact.id,
      'membership_id', v_member.id,
      'source_account_id', v_contact.account_id,
      'contact_type', v_contact.contact_type,
      'flatform_type', v_contact.flatform_type,
      'canonical_target_key', v_canonical_key,
      'snapshot_group_id', v_group.id,
      'snapshot_group_revision', v_group.revision
    ));

    -- Reuse order for one-time snapshots:
    --   1. the active canonical row;
    --   2. an active row already mapped by one of this target's aliases;
    --   3. the oldest active legacy row whose action target normalizes equally;
    --   4. a newly inserted canonical row.
    -- Legacy rows remain canonical_target_key=NULL.  Aliases and immutable
    -- origin provenance below make every later snapshot resolve to that row.
    SELECT input_data.id
    INTO v_input_id
    FROM public.auto_campaign_input_data AS input_data
    WHERE input_data.campaign_id = v_campaign.id
      AND input_data.canonical_target_key = v_canonical_key
      AND COALESCE(input_data.is_delete, false) = false
    ORDER BY input_data.id
    LIMIT 1
    FOR UPDATE;

    IF v_input_id IS NULL THEN
      SELECT input_data.id
      INTO v_input_id
      FROM public.auto_campaign_input_target_aliases AS alias
      JOIN public.auto_campaign_input_data AS input_data
        ON input_data.id = alias.input_data_id
       AND input_data.campaign_id = v_campaign.id
       AND COALESCE(input_data.is_delete, false) = false
       AND (
         input_data.canonical_target_key IS NULL
         OR input_data.canonical_target_key = v_canonical_key
       )
      WHERE alias.campaign_id = v_campaign.id
        AND alias.canonical_target_key = v_canonical_key
        AND alias.alias_key = ANY(v_aliases)
      ORDER BY input_data.id
      LIMIT 1
      FOR UPDATE OF input_data;
    END IF;

    IF v_input_id IS NULL THEN
      SELECT input_data.id
      INTO v_input_id
      FROM public.auto_campaign_input_data AS input_data
      WHERE input_data.campaign_id = v_campaign.id
        AND input_data.canonical_target_key IS NULL
        AND COALESCE(input_data.is_delete, false) = false
        AND CASE
          WHEN v_target_kind = 'phone' THEN
            public.aka_agent_internal_normalize_phone(
              COALESCE(input_data.phone, '')
            ) = v_identity_value
          WHEN v_target_kind = 'email' THEN
            lower(btrim(COALESCE(input_data.email, ''))) = v_identity_value
          WHEN v_target_kind LIKE 'facebook_%' THEN
            (
              v_scope || ':' || v_target_kind || ':' ||
              public.aka_agent_internal_normalize_facebook_identity(
                COALESCE(input_data.uid, '')
              )
            ) = ANY(v_aliases)
          ELSE
            btrim(COALESCE(input_data.uid, '')) = v_identity_value
        END
      ORDER BY input_data.id
      LIMIT 1
      FOR UPDATE;
    END IF;

    IF v_input_id IS NULL THEN
      INSERT INTO public.auto_campaign_input_data (
        campaign_id, input_id, name, phone, phone_carrier, uid, email,
        info1, info2, info3, info4, info5, status, schedule, is_delete,
        canonical_target_key, created_at
      ) VALUES (
        v_campaign.id, NULL, COALESCE(v_name, v_target_value),
        v_input_phone, v_phone_carrier, v_input_uid, v_input_email,
        v_info1, v_info2, v_info3, v_info4, v_info5,
        'chờ xử lý', p_campaign_schedule, false,
        v_canonical_key, now()
      )
      ON CONFLICT (campaign_id, canonical_target_key)
        WHERE canonical_target_key IS NOT NULL AND COALESCE(is_delete, false) = false
      DO NOTHING
      RETURNING id INTO v_input_id;

      IF v_input_id IS NULL THEN
        SELECT input_data.id
        INTO v_input_id
        FROM public.auto_campaign_input_data AS input_data
        WHERE input_data.campaign_id = v_campaign.id
          AND input_data.canonical_target_key = v_canonical_key
          AND COALESCE(input_data.is_delete, false) = false
        FOR UPDATE;
      ELSE
        v_inserted_row := true;
      END IF;
    END IF;

    INSERT INTO public.auto_campaign_input_target_aliases (
      campaign_id, alias_key, canonical_target_key, input_data_id
    )
    SELECT v_campaign.id, candidate.alias_key, v_canonical_key, v_input_id
    FROM (SELECT DISTINCT unnest(v_aliases) AS alias_key) AS candidate
    ON CONFLICT (campaign_id, alias_key) DO UPDATE
    SET input_data_id = EXCLUDED.input_data_id,
        updated_at = now()
    WHERE auto_campaign_input_target_aliases.canonical_target_key
      = EXCLUDED.canonical_target_key;

    INSERT INTO public.auto_campaign_input_origins (
      input_data_id, source_id, group_id, membership_id, batch_id,
      origin_kind, group_revision, canonical_target_key, payload_snapshot
    ) VALUES (
      v_input_id, NULL, v_group.id, v_member.id, v_batch.id,
      'group', v_group.revision, v_canonical_key, v_payload
    ) ON CONFLICT DO NOTHING;

    IF v_inserted_row THEN
      v_inserted := v_inserted + 1;
    ELSE
      v_existing := v_existing + 1;
    END IF;
  END LOOP;

  IF v_inserted > 0 THEN
    UPDATE public.auto_campaigns AS campaign
    SET schedule = p_campaign_schedule,
        original_schedule = p_campaign_schedule,
        status = p_campaign_status,
        note = CASE
          WHEN campaign.note IN ('Chờ data phù hợp', 'Chờ data mới') THEN NULL
          ELSE campaign.note
        END,
        updated_at = now()
    WHERE campaign.id = v_campaign.id;
  END IF;

  v_result := jsonb_build_object(
    'request_id', btrim(p_request_id),
    'campaign_id', v_campaign.id,
    'group_id', v_group.id,
    'group_revision', v_group.revision,
    'active_membership_count', v_active,
    'inserted_count', v_inserted,
    'already_seen_count', v_existing,
    'incompatible_count', v_incompatible,
    'conflict_count', v_conflict
  );

  UPDATE public.auto_data_ingest_batches AS batch
  SET status = 'completed', result = v_result, updated_at = now()
  WHERE batch.id = v_batch.id;

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.aka_agent_staff_runtime_scope(p_staff_id bigint, p_lock text)
 RETURNS SETOF aka_agent_staff_runtime_profile
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF p_staff_id IS NULL OR p_staff_id<=0 OR p_lock IS NULL OR p_lock NOT IN ('share','update') THEN
  RAISE EXCEPTION 'staff_runtime_scope_invalid';
 END IF;
 IF p_lock='share' THEN
  RETURN QUERY SELECT s.id,s.organization_id,s.name,s.phone,s.username,s.is_active,s.is_admin,s.is_admin_akabiz,s.use_test_workflow,s.deleted_at,s.expiration_date,s.max_running_zalo_web_accounts,s.max_running_facebook_accounts FROM public.org_staff s WHERE s.id=p_staff_id FOR SHARE OF s;
 ELSE
  RETURN QUERY SELECT s.id,s.organization_id,s.name,s.phone,s.username,s.is_active,s.is_admin,s.is_admin_akabiz,s.use_test_workflow,s.deleted_at,s.expiration_date,s.max_running_zalo_web_accounts,s.max_running_facebook_accounts FROM public.org_staff s WHERE s.id=p_staff_id FOR UPDATE OF s;
 END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_assert_automation_identity(p_staff_id bigint, p_organization_id bigint, p_auth_username text, p_auth_password text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_claim_role text;
  v_claims jsonb;
BEGIN
  v_claim_role := NULLIF(current_setting('request.jwt.claim.role', true), '');

  IF v_claim_role IS NULL THEN
    BEGIN
      v_claims := NULLIF(
        current_setting('request.jwt.claims', true),
        ''
      )::jsonb;
      v_claim_role := NULLIF(v_claims ->> 'role', '');
    EXCEPTION
      WHEN OTHERS THEN
        v_claim_role := NULL;
    END;
  END IF;

  IF v_claim_role IS NULL THEN
    v_claim_role := NULLIF(auth.jwt() ->> 'role', '');
  END IF;

  IF v_claim_role = 'service_role' THEN
    RETURN;
  END IF;

  IF p_auth_username IS NULL OR p_auth_password IS NULL THEN
    RAISE EXCEPTION 'automation_auth_required';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.org_staff AS staff
    WHERE staff.id = p_staff_id
      AND staff.organization_id = p_organization_id
      AND staff.is_active = true
      AND staff.username = p_auth_username
      AND staff.password = p_auth_password
  ) THEN
    RAISE EXCEPTION 'automation_auth_invalid';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_retry_automation_enqueue_failure_internal(p_failure_id bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_failure public.auto_automation_enqueue_failures%ROWTYPE;
  v_status text;
BEGIN
  SELECT *
  INTO v_failure
  FROM public.auto_automation_enqueue_failures AS failure
  WHERE failure.id = p_failure_id
  FOR UPDATE;

  IF NOT FOUND OR v_failure.status = 'resolved' THEN
    RETURN true;
  END IF;

  PERFORM set_config('aka_agent.automation_reconcile', 'on', true);
  PERFORM set_config(
    'aka_agent.automation_event_at',
    v_failure.event_at::text,
    true
  );

  -- UPDATE OF status deliberately re-enters the same trigger implementation.
  -- The session-local reconcile flag bypasses its no-change fast path.
  UPDATE public.auto_campaign_details AS detail
  SET status = detail.status
  WHERE detail.id = v_failure.source_campaign_detail_id;

  PERFORM set_config('aka_agent.automation_reconcile', 'off', true);
  PERFORM set_config('aka_agent.automation_event_at', '', true);

  SELECT failure.status
  INTO v_status
  FROM public.auto_automation_enqueue_failures AS failure
  WHERE failure.id = p_failure_id;

  RETURN v_status IS NULL OR v_status = 'resolved';
EXCEPTION
  WHEN OTHERS THEN
    PERFORM set_config('aka_agent.automation_reconcile', 'off', true);
    PERFORM set_config('aka_agent.automation_event_at', '', true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_non_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_platform text, p_previous_status text, p_claim_token uuid, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_platform text := lower(btrim(COALESCE(p_platform, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0 OR p_staff_id IS NULL OR p_staff_id <= 0 THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_platform NOT IN ('facebook', 'email') THEN
    RAISE EXCEPTION 'Non-Zalo runtime platform must be Facebook or Email';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  -- reset_desktop_running_statuses takes FOR UPDATE on this same row. The
  -- shared lock prevents a new account operation from entering recovery.
  SELECT staff.organization_id INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'staff_not_active'
    );
  END IF;

  SELECT account.* INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (account.organization_id IS NULL OR account.organization_id = v_organization_id)
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_found'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> v_platform
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  -- Retrying the same client-generated token is idempotent after an ambiguous
  -- network response: the caller still owns this exact account-only claim.
  IF v_account.status = 'đang chạy'
    AND v_account.runtime_operation_claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'account_id', p_account_id,
      'previous_status', v_previous_status,
      'claim_token', p_claim_token,
      'platform', v_platform
    );
  END IF;

  IF (COALESCE(p_requires_login, true) AND v_account.login_status IS DISTINCT FROM 'đã đăng nhập')
    OR v_account.status IS DISTINCT FROM v_previous_status
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  UPDATE public.auto_accounts AS account
  SET
    status = 'đang chạy',
    runtime_operation_claim_token = p_claim_token,
    updated_at = now()
  WHERE account.id = p_account_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_previous_status,
    'claim_token', p_claim_token,
    'platform', v_platform
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_capabilities record;
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'staff_not_active'
    );
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT *
  INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(
    v_organization_id
  );

  SELECT account.*
  INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'account_not_found'
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_inputs AS campaign_input
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = campaign_input.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign_input.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND input_data.status = 'đang chạy'
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'work_running'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR v_account.is_active IS NOT TRUE
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
    OR (
      COALESCE(p_requires_login, true)
      AND v_account.login_status <> 'đã đăng nhập'
    )
    OR v_account.status NOT IN ('chờ xử lý', 'tạm dừng')
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'account_not_available'
    );
  END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  IF (
    v_runtime_target = 'server'
    AND (
      v_is_web
      OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  ) OR (
    v_runtime_target = 'desktop'
    AND (
      v_is_server
      OR (
        v_is_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_is_web
        AND NOT v_is_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'reason', 'runtime_not_owner'
    );
  END IF;

  UPDATE public.auto_accounts
  SET status = 'đang chạy', updated_at = now()
  WHERE id = p_account_id;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_account.status,
    'runtime_target', v_runtime_target
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_zalo_account_runtime_operation(p_account_id bigint, p_staff_id bigint, p_runtime_target text, p_previous_status text, p_claim_token uuid, p_requires_login boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_account public.auto_accounts%ROWTYPE;
  v_organization_id bigint;
  v_runtime_target text := lower(btrim(COALESCE(p_runtime_target, '')));
  v_previous_status text := btrim(COALESCE(p_previous_status, ''));
  v_capabilities record;
  v_is_web boolean;
  v_is_server boolean;
BEGIN
  IF p_account_id IS NULL OR p_account_id <= 0
    OR p_staff_id IS NULL OR p_staff_id <= 0
  THEN
    RAISE EXCEPTION 'Account and staff IDs must be positive integers';
  END IF;
  IF v_runtime_target NOT IN ('desktop', 'server') THEN
    RAISE EXCEPTION 'Runtime target must be desktop or server';
  END IF;
  IF v_previous_status NOT IN ('chờ xử lý', 'tạm dừng') THEN
    RAISE EXCEPTION 'Previous account status must be pending or paused';
  END IF;
  IF p_claim_token IS NULL THEN
    RAISE EXCEPTION 'Runtime claim token is required';
  END IF;

  SELECT staff.organization_id
  INTO v_organization_id
  FROM public.aka_agent_staff_runtime_scope(p_staff_id, 'share') AS staff
  WHERE staff.id = p_staff_id
    AND staff.is_active = true AND public.aka_agent_staff_time_allowed(staff.id)
  ;
  IF NOT FOUND OR v_organization_id IS NULL THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'staff_not_active'
    );
  END IF;

  PERFORM pg_advisory_xact_lock_shared(
    hashtextextended('aka-agent-zalo-runtime-entitlement-mutation', 0)
  );
  SELECT *
  INTO v_capabilities
  FROM public.resolve_organization_zalo_account_capabilities(
    v_organization_id
  );

  SELECT account.*
  INTO v_account
  FROM public.auto_accounts AS account
  WHERE account.id = p_account_id
    AND account.staff_id = p_staff_id
    AND (
      account.organization_id IS NULL
      OR account.organization_id = v_organization_id
    )
  FOR UPDATE OF account;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_found'
    );
  END IF;

  IF COALESCE(v_account.is_delete, false)
    OR lower(btrim(COALESCE(v_account.flatform_type, ''))) <> 'zalo'
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  v_is_web := COALESCE(v_account.is_zalo_show_web, false);
  v_is_server := COALESCE(v_account.is_zalo_server, false);
  IF (
    v_runtime_target = 'server'
    AND (
      v_is_web
      OR NOT v_is_server
      OR NOT COALESCE(v_capabilities.qr_enabled, false)
      OR NOT COALESCE(v_capabilities.server_enabled, false)
    )
  ) OR (
    v_runtime_target = 'desktop'
    AND (
      v_is_server
      OR (
        v_is_web
        AND NOT COALESCE(v_capabilities.web_enabled, false)
      )
      OR (
        NOT v_is_web
        AND NOT v_is_server
        AND NOT COALESCE(v_capabilities.qr_enabled, false)
      )
    )
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'runtime_not_owner'
    );
  END IF;

  -- Retry of the same account-operation token remains idempotent after an
  -- ambiguous response. A campaign cannot form a unit while this account row
  -- is already owned/running by that token.
  IF v_account.status = 'đang chạy'
    AND v_account.runtime_operation_claim_token = p_claim_token
  THEN
    RETURN jsonb_build_object(
      'claimed', true,
      'account_id', p_account_id,
      'previous_status', v_previous_status,
      'claim_token', p_claim_token,
      'runtime_target', v_runtime_target
    );
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.runtime_unit_token IS NOT NULL
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaigns AS campaign
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_inputs AS campaign_input
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = campaign_input.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND campaign_input.status = 'đang chạy'
  ) OR EXISTS (
    SELECT 1
    FROM public.auto_campaign_input_data AS input_data
    JOIN public.auto_campaigns AS campaign
      ON campaign.id = input_data.campaign_id
    WHERE campaign.account_id = p_account_id
      AND campaign.staff_id = p_staff_id
      AND input_data.status = 'đang chạy'
  ) THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'work_running'
    );
  END IF;

  IF v_account.status IS DISTINCT FROM v_previous_status
    OR (
      COALESCE(p_requires_login, true)
      AND (
        v_account.is_active IS NOT TRUE
        OR v_account.login_status IS DISTINCT FROM 'đã đăng nhập'
      )
    )
  THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  UPDATE public.auto_accounts AS account
  SET status = 'đang chạy',
    runtime_operation_claim_token = p_claim_token,
    updated_at = now()
  WHERE account.id = p_account_id
    AND account.status = v_previous_status;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'claimed', false,
      'account_id', p_account_id,
      'reason', 'account_not_available'
    );
  END IF;

  RETURN jsonb_build_object(
    'claimed', true,
    'account_id', p_account_id,
    'previous_status', v_previous_status,
    'claim_token', p_claim_token,
    'runtime_target', v_runtime_target
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_phone(p text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
declare
  d text;
begin
  if p is null then
    return null;
  end if;
  d := regexp_replace(p, '[^0-9]', '', 'g');
  if d = '' then
    return '';
  end if;
  if d like '0084%' and length(d) >= 13 then
    d := '0' || substr(d, 5);
  elsif d like '84%' and length(d) >= 11 then
    d := '0' || substr(d, 3);
  end if;
  if length(d) = 9 and left(d, 1) in ('3','5','7','8','9') then
    d := '0' || d;
  end if;
  if length(d) = 11 and left(d, 1) = '0' then
    d := case left(d, 4)
      when '0162' then '032' when '0163' then '033' when '0164' then '034' when '0165' then '035'
      when '0166' then '036' when '0167' then '037' when '0168' then '038' when '0169' then '039'
      when '0120' then '070' when '0121' then '079' when '0122' then '077' when '0126' then '076'
      when '0128' then '078' when '0123' then '083' when '0124' then '084' when '0125' then '085'
      when '0127' then '081' when '0129' then '082' when '0186' then '056' when '0188' then '058'
      when '0199' then '059'
      else left(d, 4)
    end || substr(d, 5);
  end if;
  return d;
end;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_auto_automation_enqueue_failures_v185_internal(p_staff_id bigint, p_organization_id bigint, p_worker_id text, p_limit integer DEFAULT 100, p_auth_username text DEFAULT NULL::text, p_auth_password text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_failure record;
  v_processed integer := 0;
  v_resolved integer := 0;
  v_failed integer := 0;
  v_pending integer := 0;
  v_success boolean;
  v_error text;
  v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 100), 1), 500);
BEGIN
  PERFORM public.auto_assert_automation_identity(
    p_staff_id,
    p_organization_id,
    p_auth_username,
    p_auth_password
  );

  IF NULLIF(btrim(COALESCE(p_worker_id, '')), '') IS NULL
    OR length(btrim(p_worker_id)) > 200 THEN
    RAISE EXCEPTION 'invalid_automation_worker_id';
  END IF;

  FOR v_failure IN
    SELECT failure.id
    FROM public.auto_automation_enqueue_failures AS failure
    WHERE failure.staff_id = p_staff_id
      AND failure.organization_id = p_organization_id
      AND failure.status = 'pending'
      AND failure.next_attempt_at <= clock_timestamp()
    ORDER BY failure.event_at ASC, failure.id ASC
    FOR UPDATE OF failure SKIP LOCKED
    LIMIT v_limit
  LOOP
    v_processed := v_processed + 1;

    UPDATE public.auto_automation_enqueue_failures AS failure
    SET
      attempt_count = failure.attempt_count + 1,
      updated_at = clock_timestamp()
    WHERE failure.id = v_failure.id;

    BEGIN
      v_success := public.auto_retry_automation_enqueue_failure_internal(
        v_failure.id
      );

      IF v_success THEN
        v_resolved := v_resolved + 1;
      ELSE
        v_failed := v_failed + 1;
        UPDATE public.auto_automation_enqueue_failures AS failure
        SET
          next_attempt_at = clock_timestamp() + interval '30 seconds',
          updated_at = clock_timestamp()
        WHERE failure.id = v_failure.id
          AND failure.status = 'pending';
      END IF;
    EXCEPTION
      WHEN OTHERS THEN
        v_error := SQLERRM;
        v_failed := v_failed + 1;
        UPDATE public.auto_automation_enqueue_failures AS failure
        SET
          status = 'pending',
          next_attempt_at = clock_timestamp() + interval '30 seconds',
          last_error = left(v_error, 2000),
          resolved_at = NULL,
          updated_at = clock_timestamp()
        WHERE failure.id = v_failure.id;
    END;
  END LOOP;

  SELECT count(*)::integer
  INTO v_pending
  FROM public.auto_automation_enqueue_failures AS failure
  WHERE failure.staff_id = p_staff_id
    AND failure.organization_id = p_organization_id
    AND failure.status = 'pending';

  RETURN jsonb_build_object(
    'processed', v_processed,
    'resolved', v_resolved,
    'failed', v_failed,
    'pending', v_pending,
    'worker_id', btrim(p_worker_id)
  );
END;
$function$
